INSERT INTO `events_translation` (`id`, `event_id`, `amh`, `orm`, `created_at`) VALUES
(1, 1, '{"title":"ዓለም አቀፍ ማጠቃለያ 2025","location":"ሳር ቤት አካባቢ፣ ልደታ ክፍለ ከተማ","description":"የአካባቢ መሪዎችን እና ዓለም አቀፍ አጋሮችን አንድ ላይ የሚያመጣ የተሻጋሪ ተቋም ማጠቃለያ።"}', '{"title":"Walitti Qabduu Addunyaa 2025","location":"Naannoo Sar Bet, Lideta Sub-City","description":"Walitti qabduu garee adda addaa kan hoggantoota naannoo fi hirmaataa addunyaa walitti qabu."}', '2025-12-20 11:39:44'),
(1, 1, '{"title":"ዓለም አቀፍ ዲዛይን ፈተና","location":"ሳር ቤት አካባቢ፣ ልደታ ክፍለ ከተማ","description":"የከተማ እቅድ እና የማህበረሰብ ቦታዎችን የሚያሳይ የተጠናቀቀ ዲዛይን ፈተና።"}', '{"title":"Tarii Dizaynii Addunyaa","location":"Naannoo Sar Bet, Lideta Sub-City","description":"Tarii dizaynii guutamtuu kan qophii magaalaa fi bakka hawaasaa agarsiisu."}', '2025-12-20 11:39:44'),
(1, 1, '{"title":"ልዩ ሃሳብ እና ቴክኖሎጂ ቀን","location":"ሳር ቤት አካባቢ፣ ልደታ ክፍለ ከተማ","description":"የአካባቢ የሥራ ጀማሪ ኩባንያዎችን እና የከተማ አገልግሎቶችን የሚያሳይ ቴክኖሎጂ ማሳያ።"}', '{"title":"Guyyaa Qindeeffamaafi Teknooloojii","location":"Naannoo Sar Bet, Lideta Sub-City","description":"Agarsiisa teknooloojii kan daldalaa jalqabaa naannoo fi tajaajila magaalaa qopheessu."}', '2025-12-20 11:39:44'),
(1, 1, '{"title":"ስፖርት እና በዓል ቀን","location":"ሳር ቤት አካባቢ፣ ልደታ ክፍለ ከተማ","description":"በመጀመሪያ የሚያካትት የሚሆን የማህበረሰብ ስፖርት ቀን ውድድር፣ ፊት ቦሎ እና የቤተሰብ እንቅስቃሴዎች።"}', '{"title":"Guyyaa Ispoortiifi Ayyaanaa","location":"Naannoo Sar Bet, Lideta Sub-City","description":"Guyyaa ispoortii hawaasaa kan jalqabaa fiigaa, kubbaa miillaa, fi gochaalee maatii qabatu."}', '2025-12-20 11:39:44'),
(1, 1, '{"title":"የማህበረሰብ ንጽህና ቀን","location":"ሳር ቤት አካባቢ፣ ልደታ ክፍለ ከተማ","description":"ዓመቱን በማህበረሰብ አስተዳደር ጥረት ከፓርኮች እና ከመኖሪያ አካባቢዎች ጋር ለማደስ ይጀምሩ።"}', '{"title":"Guyyaa Qulqullina Hawaasaa","location":"Naannoo Sar Bet, Lideta Sub-City","description":"Waggaa akka qulqullina hawaasaatiin paarkota fi naannoo jireenyaa deebisuuf jalqabi."}', '2025-12-20 11:39:44'),
(1, 1, '{"title":"የወጣቶች ኮድ ማውጣት አውደ ማሰልጠኛ","location":"ዲጂታል አገልግሎት ማዕከል፣ ልደታ ክፍለ ከተማ","description":"ለአካባቢው ወጣቶች መሰረታዊ ኮድ ማውጣት እና የሮቦት ክህሎቶችን ለመማር በእጅ የሚሰጥ አውደ ማሰልጠኛ።"}', '{"title":"Waaksii Koodii Daa\'immaa","location":"Giddugaleessa Tajaajilaa Dijitaalaa, Lideta Sub-City","description":"Waaksii harka qabu daa\'immaa naannoo akka koodii jalqabaa fi qophii roobootiksii baratuuf."}', '2025-12-20 11:39:44'),
(1, 1, '{"title":"የባህል ቅርስ ቀን","status":"የሚመጡ","location":"የባህል ማዕከል፣ ልደታ ክፍለ ከተማ","description":"በአካባቢው ጥበብ፣ ሙዚቃ እና ባህላዊ እጅ ሥራ በአማካይነት በዓል እና በማሳያዎች ማስተዋወቅ።"}', '{"title":"Guyyaa Duudhaa Aadaa","status":"Dhufan","location":"Giddugaleessa Aadaa, Lideta Sub-City","description":"Baga aadaa naannoo, muuziqaa, fi hojii harka aadaa kan agarsiisaafi taphatuudhaan."}', '2025-12-20 11:39:44'),
(1, 1, '{"title":"የነፍሳት ቅነሳ ዘመቻ","status":"የሚመጡ","location":"የገበያ አደባባይ፣ ልደታ ክፍለ ከተማ","description":"ለነዋሪዎች ስለ ማደራጀት እና ዘላቂ የነፍሳት አስተዳደር የሚያስተምር የትምህርት ክንውን።"}', '{"title":"Kampaanii Hir\'isa Saaphanaa","status":"Dhufan","location":"Bakka Gabaasaa, Lideta Sub-City","description":"Taatee barnootaa kan jiraattoota irra deddeebi\'ii fi bulchiinsa saaphanaa dhaabbataa barsiisu."}', '2025-12-20 11:39:44'),
(1, 1, '{"title":"የህዝብ ደህንነት አውደ ማሰልጠኛ","status":"የሚመጡ","location":"የማህበረሰብ አደባባይ፣ ልደታ ክፍለ ከተማ","description":"በእሳት ደህንነት፣ የመጀመሪያ እርዳታ እና የድንገተኛ ሁኔታ ዝግጅት ላይ በይነተገናኝ ክፍሎች።"}', '{"title":"Waaksii Nagaa Ummataa","status":"Dhufan","location":"Hollaa Hawaasaa, Lideta Sub-City","description":"Kuusoota walitti dhufeenyaa eegumsa abiddaa, gargaarsa jalqabaa, fi qophii yeroo barbaachisaa irratti."}', '2025-12-20 11:39:44'),
(1, 1, '{"title":"የአካባቢ ገበሬዎች ገበያ","status":"የሚመጡ","location":"የከተማ አደባባይ፣ ልደታ ክፍለ ከተማ","description":"ነዋሪዎች በአዲስ ምርቶች እና በእጅ ሥራ ዕቃዎች ለመግዛት የአንድ ቀን ገበያ።"}', '{"title":"Gabaasa Qotee Bulaa Naannoo","status":"Dhufan","location":"Bakka Magaalaa, Lideta Sub-City","description":"Gabaasa guyyaa tokkoof kan jiraattoota akka oomisha haaraa fi meeshaa harka qabatanii bitatanii gahuuf."}', '2025-12-20 11:39:44'),
(1, 1, '{"title":"የበረዶ ወቅት ስፖርት በዓል","status":"የሚመጡ","location":"የስፖርት መስኮች፣ ልደታ ክፍለ ከተማ","description":"ለቤተሰቦች እና ለወጣቶች አስደሳች የበረዶ ወቅት ጨዋታዎች እና ውድድሮች።"}', '{"title":"Ayyaana Ispoortii Ganna","status":"Dhufan","location":"Bakka Ispoortii, Lideta Sub-City","description":"Taphaalee ganna fi walii galtee maatiifi daa\'immaa kan gammachiisu."}', '2025-12-20 11:39:44'),
(1, 1, '{"title":"ጥበብ በፓርክ","status":"የሚመጡ","location":"ማዕከላዊ ፓርክ፣ ልደታ ክፍለ ከተማ","description":"በአካባቢው አርቲስቶች እና ተማሪዎች ስራዎችን የሚያሳይ ውጭ የጥበብ ማሳያ።"}', '{"title":"Fannoo Paarkii Keessatti","status":"Dhufan","location":"Paarkii Giddu Galeessaa, Lideta Sub-City","description":"Agarsiisa fannoo alaa kan qaama aartistootaa fi barattoota naannoo agarsiisu."}', '2025-12-20 11:39:44'),
(1, 1, '{"title":"የከተማ እድገት ላይ የማህበረሰብ መድረክ","status":"የሚመጡ","location":"የከተማ ምክር ቤት አደባባይ፣ ልደታ ክፍለ ከተማ","description":"ስለ አካባቢያዊ መሠረተ ልማት ፕሮጀክቶች እና የወደፊት የከተማ እቅድ ተቋሞች ውይይት።"}', '{"title":"Murtii Hawaasaa Hundeeffama Magaalaa Irratti","status":"Dhufan","location":"Hollaa Murtii Magaalaa, Lideta Sub-City","description":"Mari\'i piroojektota bu\'uuraa naannoo fi kaayyoo qophii magaalaa fuula duraa irratti."}', '2025-12-20 11:39:44');
INSERT INTO `news` (`id`, `title`, `short_description`, `description`, `category`, `photo`, `created_at`, `updated_at`) VALUES
(1, 'Annual Health Fair a Success', 'Over 500 residents benefit from free health screenings', 'The annual health fair attracted over 500 residents who received free health screenings and medical consultations.', 'Health', NULL, '2025-12-05 07:30:00', '2025-12-17 19:47:30'),
(1, 'Local School Wins National Science Competition', 'Local students win first place in national science competition', 'Students from Lideta High School won first place in the national science fair with their innovative renewable energy project.', 'Education', '{"url":"/uploads/science-fair.jpg","name":"science-fair.jpg"}', '2025-12-01 11:15:00', '2025-12-17 19:47:30'),
(1, 'Road Construction Project Begins', 'Infrastructure improvements begin in western part of the city', 'The much-anticipated road construction project in the western part of the sub-city has begun, expected to improve traffic flow.', 'Infrastructure', '[{"url":"/uploads/road-construction.jpg","name":"road-construction.jpg"}]', '2025-11-28 05:45:00', '2025-12-17 19:47:30'),
(1, 'New Waste Management Initiative Launched', 'New recycling program promotes environmental sustainability', 'A new recycling program has been launched to promote environmental sustainability in our community.', 'Environment', '[{"url":"/uploads/recycling.jpg","name":"recycling.jpg"}]', '2025-11-25 08:20:00', '2025-12-17 19:47:30'),
(1, 'Lideta Launches New Digital Service Center', 'New digital service center improves citizen access to municipal services', 'The Lideta Sub-City administration has launched a new digital service center designed to streamline services such as ID processing, tax inquiries, and community applications.', 'Technology', '[{"url":"/uploads/digital-center.jpg","name":"digital-center.jpg"}]', '2025-11-22 06:00:00', '2025-12-17 19:47:30'),
(1, 'Sub-City Undertakes Major Road Maintenance', 'Road maintenance project begins across multiple neighborhoods', 'A large-scale road maintenance initiative has begun to repair potholes and improve safety across several districts in the sub-city.', 'Infrastructure', '[{"url":"/uploads/road-maintenance.jpg","name":"road-maintenance.jpg"}]', '2025-11-18 04:30:00', '2025-12-17 19:47:30'),
(1, 'Local Library Expands Youth Programs', 'Youth programs expanded with new reading and computer classes', 'The Lideta public library has expanded its youth programs with new reading clubs, computer literacy classes, and weekend workshops.', 'Education', '[{"url":"/uploads/library-youth.jpg","name":"library-youth.jpg"}]', '2025-11-14 10:10:00', '2025-12-17 19:47:30'),
(1, 'Community Garden Initiative Grows', 'Residents volunteer to expand the community garden spaces', 'The community garden project continues to grow as local residents volunteer to plant vegetables, herbs, and flowers in shared public spaces.', 'Environment', '[{"url":"/uploads/community-garden.jpg","name":"community-garden.jpg"}]', '2025-11-10 07:40:00', '2025-12-17 19:47:30'),
(1, 'Lideta Hosts Annual Business Forum', 'Local business leaders gather to discuss growth strategies', 'The annual business forum brought together entrepreneurs and officials to discuss investment opportunities and strategies for local economic growth.', 'Business', '[{"url":"/uploads/business-forum.jpg","name":"business-forum.jpg"}]', '2025-11-07 05:55:00', '2025-12-17 19:47:30'),
(1, 'Public Park Renovation Completed', 'Major renovation of central park completed', 'Renovation of the central public park has been completed, featuring new playgrounds, walking paths, and improved lighting.', 'Community', '[{"url":"/uploads/park-renovation.jpg","name":"park-renovation.jpg"}]', '2025-11-03 12:20:00', '2025-12-17 19:47:30'),
(1, 'Youth Sports League Kicks Off', 'New youth sports season begins with football and athletics competitions', 'The youth sports league has officially begun, encouraging participation in football, athletics, and other activities to promote healthy living.', 'Sports', '[{"url":"/uploads/youth-sports.jpg","name":"youth-sports.jpg"}]', '2025-10-25 08:15:00', '2025-12-17 19:47:30'),
(1, 'Lideta Sub-City Launches Major Road Infrastructure Upgrade', 'Lideta Sub-City Administration has officially launched a comprehensive road rehabilitation project covering 12 key corridors across the sub-city.', 'Lideta Sub-City Administration has officially launched a comprehensive road rehabilitation project covering 12 key corridors across the sub-city. The project, funded through a joint initiative between the Addis Ababa City Administration and local government budget, aims to address long-standing transportation challenges and improve daily commutes for over 300,000 residents.\n\nThe rehabilitation program includes road widening, installation of modern drainage systems, pedestrian walkways, and street lighting upgrades. Construction crews have already begun work on the first phase, targeting the busiest arterial roads that connect residential neighborhoods to commercial zones.\n\nSub-City Administrator emphasized that this project is a milestone in the administration\'s five-year development plan. "We are committed to delivering world-class infrastructure that reflects the aspirations of our residents," she stated during the project launch ceremony.\n\nThe entire project is expected to be completed within 18 months, with phase one set for delivery in the next six months. Residents are encouraged to follow traffic management advisories during the construction period.', 'Infrastructure', '{"name":"infrastructure.jpg","path":"https://images.unsplash.com/photo-1594708767771-a5a7c6e02acb?w=1200&q=80"}', '2026-08-23 07:05:13', '2026-08-23 07:05:13'),
(1, 'Free Health Screening Campaign Reaches 15,000 Residents', 'The Lideta Sub-City Health Office completed a three-week free health screening campaign providing services to over 15,000 residents across 8 health centers.', 'The Lideta Sub-City Health Office has successfully completed a three-week free health screening campaign, providing essential health services to over 15,000 residents across 8 community health centers throughout the sub-city.\n\nThe campaign, held in partnership with Addis Ababa Health Bureau and several NGO partners, offered screenings for diabetes, hypertension, tuberculosis, and maternal health. Mobile units were deployed to underserved neighborhoods to ensure no resident was left without access to care.\n\nHealth Office Director reported that over 2,300 residents were referred for follow-up treatment, and 450 previously undiagnosed cases of hypertension were identified. "Early detection saves lives," the director said. "This campaign is part of our commitment to preventive healthcare."\n\nThe sub-city administration has announced that similar campaigns will be held quarterly. Residents who could not attend are encouraged to visit their nearest health center for free consultations during the next campaign period.', 'Health', '{"name":"health.jpg","path":"https://images.unsplash.com/photo-1532938911079-1b06ac7ceec7?w=1200&q=80"}', '2026-08-23 07:05:14', '2026-08-23 07:05:14'),
(1, 'New Primary Schools Open in Three Neighborhoods', 'Three new fully equipped primary schools have been inaugurated across Lideta Sub-City, adding 2,400 new student seats to ease classroom overcrowding.', 'Three brand-new, fully equipped primary schools have been officially inaugurated across Lideta Sub-City, adding 2,400 new student seats and significantly easing the chronic classroom overcrowding that has affected educational quality for years.\n\nEach school features modern classrooms, a computer laboratory, a library, sanitation facilities, and a dedicated sports ground. The construction was financed through the city\'s education fund supplemented by community contributions and private sector partnerships.\n\nThe Addis Ababa Education Bureau commended Lideta Sub-City Administration for prioritizing education. The bureau noted that the student-to-classroom ratio in the sub-city has improved from 65:1 to 45:1 following the new openings.\n\nParents and community leaders attended the inauguration ceremony and praised the administration for delivering the schools on schedule. Student enrollment for the next academic year is now open, with priority given to students from the surrounding neighborhoods.', 'Education', '{"name":"education.jpg","path":"https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=1200&q=80"}', '2026-08-23 07:05:15', '2026-08-23 07:05:15'),
(1, 'Lideta Sub-City Hosts Inter-Kebele Community Dialogue Forum', 'Over 500 community leaders, youth representatives, and residents gathered for a two-day inter-kebele dialogue forum focused on urban development priorities.', 'More than 500 community leaders, youth representatives, women\'s groups, and residents from across Lideta Sub-City gathered for a two-day inter-kebele community dialogue forum, focusing on urban development priorities and public service improvement.\n\nThe forum, organized by the Sub-City Administration\'s Community Affairs Office, featured panel discussions, working groups, and open floor sessions. Participants raised issues including waste management, traffic congestion, public park maintenance, and access to municipal services.\n\nAmong the key outcomes of the forum was an agreement to establish a permanent Community Advisory Council that will meet quarterly to provide feedback to the administration. The council will include representatives from all 10 kebeles within the sub-city.\n\n"Governance is most effective when it is participatory," said the Sub-City Administrator. "This forum demonstrates that when we listen to our residents, we can build a more responsive administration." A formal report of the forum\'s recommendations will be published within 30 days.', 'Events', '{"name":"meeting.jpg","path":"https://images.unsplash.com/photo-1517048676732-d65bc937f952?w=1200&q=80"}', '2026-08-23 07:05:15', '2026-08-23 07:05:15'),
(1, 'Green Lideta: 50,000 Trees Planted in Sub-City Beautification Drive', 'Lideta Sub-City launched its landmark "Green Lideta" initiative, mobilizing residents and volunteers to plant 50,000 trees across parks, streets, and schools.', 'Lideta Sub-City Administration launched its landmark "Green Lideta" environmental initiative, mobilizing over 3,000 residents, school students, and volunteers to plant 50,000 trees across parks, street medians, school compounds, and open green spaces throughout the sub-city in a single weekend.\n\nThe initiative is part of Addis Ababa\'s citywide green infrastructure program and aims to combat urban heat islands, improve air quality, and create more pleasant public spaces. Species selected include indigenous trees such as Warka (Ficus thonningii), Tidh (Juniperus procera), and various fruit-bearing trees that also benefit communities.\n\nThe Environment Office announced that follow-up maintenance teams will be assigned to each planting site for the next two years to ensure survival rates above 80%. A digital map of all planted sites will be made publicly available so residents can monitor progress.\n\n"Every tree we plant today is a gift to future generations," said the Sub-City Environment Officer. Community members who participated received certificates of recognition from the sub-city administration.', 'Environment', '{"name":"environment.jpg","path":"https://images.unsplash.com/photo-1504711434969-e33886168f5c?w=1200&q=80"}', '2026-08-23 07:05:16', '2026-08-23 07:05:16'),
(1, 'Lideta Sub-City Digital Services Portal Goes Live', 'Residents can now access over 30 municipal services online through the newly launched Lideta Digital Services Portal, reducing wait times and improving transparency.', 'Lideta Sub-City Administration has officially launched its Digital Services Portal, allowing residents to access more than 30 municipal services online without the need to visit government offices in person. The portal went live following a successful six-month pilot program.\n\nServices available through the portal include trade license renewal, birth and marriage certificate applications, property registration, utility complaint submission, and tracking of complaint resolution status. The system is accessible via both desktop and mobile devices and is available in Amharic, Oromo, and English.\n\nThe portal is part of a broader e-governance strategy that Addis Ababa City Administration has been rolling out across all sub-cities. User registration requires a valid national ID and a mobile phone number for verification.\n\n"This is a significant step toward making government services more accessible and reducing bureaucratic friction," said the Head of the ICT Department. Over 1,200 residents have already registered in the first week since launch, with trade license renewal being the most popular service.', 'Technology', '{"name":"community.jpg","path":"https://images.unsplash.com/photo-1591115765373-5207764f72e7?w=1200&q=80"}', '2026-08-23 07:05:17', '2026-08-23 07:05:17'),
(1, 'Sub-City Administration Cracks Down on Illegal Construction', 'Lideta Sub-City has demolished 47 illegally constructed structures and issued formal warnings to 120 property owners in a sweeping enforcement campaign.', 'In a decisive enforcement action, Lideta Sub-City Administration has demolished 47 illegally constructed structures and issued formal warnings to 120 additional property owners over a six-week period, as part of an intensified campaign to enforce urban planning regulations.\n\nThe structures included encroachments on public roads and pedestrian paths, unauthorized commercial buildings in residential zones, and constructions without valid permits. The campaign was coordinated between the Sub-City Urban Planning Office, the Addis Ababa City Administration, and local police.\n\nThe Urban Planning Office noted that illegal construction has been one of the primary obstacles to implementing the sub-city\'s master plan. Property owners who demolish illegal structures voluntarily within the given notice period will not face additional penalties.\n\nResidents are reminded to obtain valid construction permits before beginning any building work. The Sub-City Urban Planning Office offers free consultations on permit requirements every Monday and Wednesday from 8:30 AM to 12:30 PM.', 'Security', '{"name":"road.jpg","path":"https://images.unsplash.com/photo-1566438480900-0609be27a4be?w=1200&q=80"}', '2026-08-23 07:05:18', '2026-08-23 07:05:18'),
(1, 'Youth Skills Training Center Enrolls 800 Young People', 'The Lideta Sub-City Youth and Sports Office has enrolled 800 young people in its latest round of vocational skills training programs covering IT, tailoring, and construction trades.', 'The Lideta Sub-City Youth and Sports Office has successfully enrolled 800 young people, aged 18 to 35, in its latest round of vocational skills training programs. The training, which covers information technology, tailoring and fashion design, carpentry, masonry, and electrical installation, is designed to equip young people with marketable skills and reduce youth unemployment.\n\nThe program is delivered in partnership with TVET institutions and private sector employers who have committed to offering employment opportunities to graduates. Training runs for three to six months depending on the track, with certification provided by the Ethiopian TVET Agency upon completion.\n\nPrevious rounds of the program have resulted in employment rates above 70% for graduates within six months of certification. The Youth Office noted that demand for the program has increased by 35% compared to the previous year, indicating strong community interest.\n\nYoung people interested in the next enrollment round are encouraged to register at the Sub-City Youth and Sports Office. Enrollment priority is given to young women, individuals with disabilities, and those from low-income households.', 'Education', '{"name":"school.jpg","path":"https://images.unsplash.com/photo-1503676260728-1c00da094a0b?w=1200&q=80"}', '2026-08-23 07:05:18', '2026-08-23 07:05:18'),
(1, 'Renovated Lideta Central Market Opens to Merchants and Public', 'After 14 months of construction, the fully renovated Lideta Central Market has re-opened, featuring modern stalls, improved sanitation, and fire safety systems.', 'After 14 months of intensive construction, the fully renovated Lideta Central Market has officially re-opened its doors to merchants and the public. The renovation project transformed the market from a congested, deteriorating facility into a modern, organized commercial hub with capacity for over 800 permanent stalls.\n\nKey improvements include dedicated zones for fresh produce, clothing, electronics, and food service; a centralized waste management system; modern sanitation blocks; integrated fire suppression systems; and CCTV surveillance for improved security.\n\nMerchants who were temporarily relocated during the construction period have been assigned new permanent stalls on a priority basis. The Sub-City Trade and Industry Office noted that rental rates for stalls have been maintained at pre-renovation levels to ease the transition.\n\n"This market is the economic heart of our sub-city," said the Sub-City Administrator at the inauguration ceremony. "Investing in it is investing in the livelihoods of thousands of families." The market is expected to generate 200 new permanent jobs through expanded service facilities.', 'Infrastructure', '{"name":"clinic.jpg","path":"https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=1200&q=80"}', '2026-08-23 07:05:19', '2026-08-23 07:05:19'),
(1, 'Lideta Sub-City Recognized for Excellence in Public Service Delivery', 'Lideta Sub-City Administration received the Addis Ababa City Administration\'s Award for Excellence in Public Service Delivery for the second consecutive year.', 'Lideta Sub-City Administration has received the Addis Ababa City Administration\'s prestigious Award for Excellence in Public Service Delivery for the second consecutive year, recognizing outstanding performance across service delivery quality, citizen satisfaction, and administrative transparency.\n\nThe award, presented at the annual Addis Ababa Good Governance Conference, cited Lideta\'s achievements in reducing average service wait times by 42%, achieving a citizen satisfaction score of 87% in the annual survey, and implementing a fully functional digital complaint management system.\n\nThe Sub-City Administrator accepted the award on behalf of the administration\'s 1,200 staff members. "This recognition belongs to every employee who shows up every day committed to serving our residents, and to every resident who holds us accountable," she said.\n\nThe administration has committed to maintaining high service standards and announced plans to introduce three new digital services in the coming quarter, including an online property tax payment portal and a live tracking system for infrastructure maintenance requests.', 'Events', '{"name":"urban.jpg","path":"https://images.unsplash.com/photo-1464938050520-ef2270bb8ce8?w=1200&q=80"}', '2026-08-23 07:05:20', '2026-08-23 07:05:20'),
(1, 'Lideta Sub-City Launches Major Road Infrastructure Upgrade', 'Lideta Sub-City Administration has officially launched a comprehensive road rehabilitation project covering 12 key corridors across the sub-city.', 'Lideta Sub-City Administration has officially launched a comprehensive road rehabilitation project covering 12 key corridors across the sub-city. The project, funded through a joint initiative between the Addis Ababa City Administration and local government budget, aims to address long-standing transportation challenges and improve daily commutes for over 300,000 residents.\n\nThe rehabilitation program includes road widening, installation of modern drainage systems, pedestrian walkways, and street lighting upgrades. Construction crews have already begun work on the first phase, targeting the busiest arterial roads that connect residential neighborhoods to commercial zones.\n\nSub-City Administrator emphasized that this project is a milestone in the administration\'s five-year development plan. "We are committed to delivering world-class infrastructure that reflects the aspirations of our residents," she stated during the project launch ceremony.\n\nThe entire project is expected to be completed within 18 months, with phase one set for delivery in the next six months. Residents are encouraged to follow traffic management advisories during the construction period.', 'Infrastructure', '{"name":"infrastructure.jpg","path":"https://images.unsplash.com/photo-1594708767771-a5a7c6e02acb?w=1200&q=80"}', '2026-08-23 07:05:38', '2026-08-23 07:05:38'),
(1, 'Free Health Screening Campaign Reaches 15,000 Residents', 'The Lideta Sub-City Health Office completed a three-week free health screening campaign providing services to over 15,000 residents across 8 health centers.', 'The Lideta Sub-City Health Office has successfully completed a three-week free health screening campaign, providing essential health services to over 15,000 residents across 8 community health centers throughout the sub-city.\n\nThe campaign, held in partnership with Addis Ababa Health Bureau and several NGO partners, offered screenings for diabetes, hypertension, tuberculosis, and maternal health. Mobile units were deployed to underserved neighborhoods to ensure no resident was left without access to care.\n\nHealth Office Director reported that over 2,300 residents were referred for follow-up treatment, and 450 previously undiagnosed cases of hypertension were identified. "Early detection saves lives," the director said. "This campaign is part of our commitment to preventive healthcare."\n\nThe sub-city administration has announced that similar campaigns will be held quarterly. Residents who could not attend are encouraged to visit their nearest health center for free consultations during the next campaign period.', 'Health', '{"name":"health.jpg","path":"https://images.unsplash.com/photo-1532938911079-1b06ac7ceec7?w=1200&q=80"}', '2026-08-23 07:05:39', '2026-08-23 07:05:39'),
(1, 'New Primary Schools Open in Three Neighborhoods', 'Three new fully equipped primary schools have been inaugurated across Lideta Sub-City, adding 2,400 new student seats to ease classroom overcrowding.', 'Three brand-new, fully equipped primary schools have been officially inaugurated across Lideta Sub-City, adding 2,400 new student seats and significantly easing the chronic classroom overcrowding that has affected educational quality for years.\n\nEach school features modern classrooms, a computer laboratory, a library, sanitation facilities, and a dedicated sports ground. The construction was financed through the city\'s education fund supplemented by community contributions and private sector partnerships.\n\nThe Addis Ababa Education Bureau commended Lideta Sub-City Administration for prioritizing education. The bureau noted that the student-to-classroom ratio in the sub-city has improved from 65:1 to 45:1 following the new openings.\n\nParents and community leaders attended the inauguration ceremony and praised the administration for delivering the schools on schedule. Student enrollment for the next academic year is now open, with priority given to students from the surrounding neighborhoods.', 'Education', '{"name":"education.jpg","path":"https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=1200&q=80"}', '2026-08-23 07:05:39', '2026-08-23 07:05:39'),
(1, 'Lideta Sub-City Hosts Inter-Kebele Community Dialogue Forum', 'Over 500 community leaders, youth representatives, and residents gathered for a two-day inter-kebele dialogue forum focused on urban development priorities.', 'More than 500 community leaders, youth representatives, women\'s groups, and residents from across Lideta Sub-City gathered for a two-day inter-kebele community dialogue forum, focusing on urban development priorities and public service improvement.\n\nThe forum, organized by the Sub-City Administration\'s Community Affairs Office, featured panel discussions, working groups, and open floor sessions. Participants raised issues including waste management, traffic congestion, public park maintenance, and access to municipal services.\n\nAmong the key outcomes of the forum was an agreement to establish a permanent Community Advisory Council that will meet quarterly to provide feedback to the administration. The council will include representatives from all 10 kebeles within the sub-city.\n\n"Governance is most effective when it is participatory," said the Sub-City Administrator. "This forum demonstrates that when we listen to our residents, we can build a more responsive administration." A formal report of the forum\'s recommendations will be published within 30 days.', 'Events', '{"name":"meeting.jpg","path":"https://images.unsplash.com/photo-1517048676732-d65bc937f952?w=1200&q=80"}', '2026-08-23 07:05:40', '2026-08-23 07:05:40'),
(1, 'Green Lideta: 50,000 Trees Planted in Sub-City Beautification Drive', 'Lideta Sub-City launched its landmark "Green Lideta" initiative, mobilizing residents and volunteers to plant 50,000 trees across parks, streets, and schools.', 'Lideta Sub-City Administration launched its landmark "Green Lideta" environmental initiative, mobilizing over 3,000 residents, school students, and volunteers to plant 50,000 trees across parks, street medians, school compounds, and open green spaces throughout the sub-city in a single weekend.\n\nThe initiative is part of Addis Ababa\'s citywide green infrastructure program and aims to combat urban heat islands, improve air quality, and create more pleasant public spaces. Species selected include indigenous trees such as Warka (Ficus thonningii), Tidh (Juniperus procera), and various fruit-bearing trees that also benefit communities.\n\nThe Environment Office announced that follow-up maintenance teams will be assigned to each planting site for the next two years to ensure survival rates above 80%. A digital map of all planted sites will be made publicly available so residents can monitor progress.\n\n"Every tree we plant today is a gift to future generations," said the Sub-City Environment Officer. Community members who participated received certificates of recognition from the sub-city administration.', 'Environment', '{"name":"environment.jpg","path":"https://images.unsplash.com/photo-1504711434969-e33886168f5c?w=1200&q=80"}', '2026-08-23 07:05:40', '2026-08-23 07:05:40'),
(1, 'Lideta Sub-City Digital Services Portal Goes Live', 'Residents can now access over 30 municipal services online through the newly launched Lideta Digital Services Portal, reducing wait times and improving transparency.', 'Lideta Sub-City Administration has officially launched its Digital Services Portal, allowing residents to access more than 30 municipal services online without the need to visit government offices in person. The portal went live following a successful six-month pilot program.\n\nServices available through the portal include trade license renewal, birth and marriage certificate applications, property registration, utility complaint submission, and tracking of complaint resolution status. The system is accessible via both desktop and mobile devices and is available in Amharic, Oromo, and English.\n\nThe portal is part of a broader e-governance strategy that Addis Ababa City Administration has been rolling out across all sub-cities. User registration requires a valid national ID and a mobile phone number for verification.\n\n"This is a significant step toward making government services more accessible and reducing bureaucratic friction," said the Head of the ICT Department. Over 1,200 residents have already registered in the first week since launch, with trade license renewal being the most popular service.', 'Technology', '{"name":"community.jpg","path":"https://images.unsplash.com/photo-1591115765373-5207764f72e7?w=1200&q=80"}', '2026-08-23 07:05:43', '2026-08-23 07:05:43'),
(1, 'Sub-City Administration Cracks Down on Illegal Construction', 'Lideta Sub-City has demolished 47 illegally constructed structures and issued formal warnings to 120 property owners in a sweeping enforcement campaign.', 'In a decisive enforcement action, Lideta Sub-City Administration has demolished 47 illegally constructed structures and issued formal warnings to 120 additional property owners over a six-week period, as part of an intensified campaign to enforce urban planning regulations.\n\nThe structures included encroachments on public roads and pedestrian paths, unauthorized commercial buildings in residential zones, and constructions without valid permits. The campaign was coordinated between the Sub-City Urban Planning Office, the Addis Ababa City Administration, and local police.\n\nThe Urban Planning Office noted that illegal construction has been one of the primary obstacles to implementing the sub-city\'s master plan. Property owners who demolish illegal structures voluntarily within the given notice period will not face additional penalties.\n\nResidents are reminded to obtain valid construction permits before beginning any building work. The Sub-City Urban Planning Office offers free consultations on permit requirements every Monday and Wednesday from 8:30 AM to 12:30 PM.', 'Security', '{"name":"road.jpg","path":"https://images.unsplash.com/photo-1566438480900-0609be27a4be?w=1200&q=80"}', '2026-08-23 07:05:44', '2026-08-23 07:05:44'),
(1, 'Youth Skills Training Center Enrolls 800 Young People', 'The Lideta Sub-City Youth and Sports Office has enrolled 800 young people in its latest round of vocational skills training programs covering IT, tailoring, and construction trades.', 'The Lideta Sub-City Youth and Sports Office has successfully enrolled 800 young people, aged 18 to 35, in its latest round of vocational skills training programs. The training, which covers information technology, tailoring and fashion design, carpentry, masonry, and electrical installation, is designed to equip young people with marketable skills and reduce youth unemployment.\n\nThe program is delivered in partnership with TVET institutions and private sector employers who have committed to offering employment opportunities to graduates. Training runs for three to six months depending on the track, with certification provided by the Ethiopian TVET Agency upon completion.\n\nPrevious rounds of the program have resulted in employment rates above 70% for graduates within six months of certification. The Youth Office noted that demand for the program has increased by 35% compared to the previous year, indicating strong community interest.\n\nYoung people interested in the next enrollment round are encouraged to register at the Sub-City Youth and Sports Office. Enrollment priority is given to young women, individuals with disabilities, and those from low-income households.', 'Education', '{"name":"school.jpg","path":"https://images.unsplash.com/photo-1503676260728-1c00da094a0b?w=1200&q=80"}', '2026-08-23 07:05:44', '2026-08-23 07:05:44'),
(1, 'Renovated Lideta Central Market Opens to Merchants and Public', 'After 14 months of construction, the fully renovated Lideta Central Market has re-opened, featuring modern stalls, improved sanitation, and fire safety systems.', 'After 14 months of intensive construction, the fully renovated Lideta Central Market has officially re-opened its doors to merchants and the public. The renovation project transformed the market from a congested, deteriorating facility into a modern, organized commercial hub with capacity for over 800 permanent stalls.\n\nKey improvements include dedicated zones for fresh produce, clothing, electronics, and food service; a centralized waste management system; modern sanitation blocks; integrated fire suppression systems; and CCTV surveillance for improved security.\n\nMerchants who were temporarily relocated during the construction period have been assigned new permanent stalls on a priority basis. The Sub-City Trade and Industry Office noted that rental rates for stalls have been maintained at pre-renovation levels to ease the transition.\n\n"This market is the economic heart of our sub-city," said the Sub-City Administrator at the inauguration ceremony. "Investing in it is investing in the livelihoods of thousands of families." The market is expected to generate 200 new permanent jobs through expanded service facilities.', 'Infrastructure', '{"name":"clinic.jpg","path":"https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=1200&q=80"}', '2026-08-23 07:05:45', '2026-08-23 07:05:45'),
(1, 'Lideta Sub-City Recognized for Excellence in Public Service Delivery', 'Lideta Sub-City Administration received the Addis Ababa City Administration\'s Award for Excellence in Public Service Delivery for the second consecutive year.', 'Lideta Sub-City Administration has received the Addis Ababa City Administration\'s prestigious Award for Excellence in Public Service Delivery for the second consecutive year, recognizing outstanding performance across service delivery quality, citizen satisfaction, and administrative transparency.\n\nThe award, presented at the annual Addis Ababa Good Governance Conference, cited Lideta\'s achievements in reducing average service wait times by 42%, achieving a citizen satisfaction score of 87% in the annual survey, and implementing a fully functional digital complaint management system.\n\nThe Sub-City Administrator accepted the award on behalf of the administration\'s 1,200 staff members. "This recognition belongs to every employee who shows up every day committed to serving our residents, and to every resident who holds us accountable," she said.\n\nThe administration has committed to maintaining high service standards and announced plans to introduce three new digital services in the coming quarter, including an online property tax payment portal and a live tracking system for infrastructure maintenance requests.', 'Events', '{"name":"urban.jpg","path":"https://images.unsplash.com/photo-1464938050520-ef2270bb8ce8?w=1200&q=80"}', '2026-08-23 07:05:45', '2026-08-23 07:05:45');
INSERT INTO `news_translation` (`id`, `news_id`, `amh`, `orm`, `created_at`) VALUES
(1, 1, '{"title":"ዓመታዊ የጤና ገበያ ስኬት አስመዝግቧል","category":"ጤና","description":"ዓመታዊው የጤና ገበያ ከ500 በላይ ነዋሪዎችን አሳስቷል እነሱም ነጻ የጤና ፈተናዎችን እና የሕክምና አማካሪዎችን ተቀብለዋል።","shortDescription":""}', '{"title":"Gaaffii Fayyaa Waggaa Waggaa Milkaa\'inaan Xumurame","category":"Fayyaa","description":"Gaaffii fayyaa waggaa waggaa jiraattota 500 ol ta\'an kan fayyaa bilisaa fi gorsa qoricha argatanii gammachiise.","shortDescription":""}', '2025-12-19 09:54:23'),
(1, 1, '{"title":"የአካባቢ ትምህርት ቤት በአገር አቀፍ የሳይንስ ውድድር አሸንቷል","category":"ትምህርት","description":"ከልደታ ሁለተኛ ደረጃ ትምህርት ቤት የመጡ ተማሪዎች የአገር አቀፍ የሳይንስ ገበያ በአዲስ የሚቀይር ኃይል ፕሮጀክታቸው አሸንተዋል።","shortDescription":"የአካባቢ ተማሪዎች በአገር አቀፍ የሳይንስ ውድድር አሸንተዋል"}', '{"title":"Mana Barumsaa Naannoo Imalaan Walii Galtee Saayinsii Aangoo Itoophiyaa Irratti Mo\'ate","category":"Barnoota","description":"Barattoonni mana barumsaa sadarkaa 2ffaa Lideta irraa ta\'an imalaan qindeessaa humnaa guddisaa kan isaanii argatanii walii galtee saayinsii aangoo Itoophiyaa irratti mo\'atan.","shortDescription":"Barattoonni naannoo walii galtee saayinsii aangoo Itoophiyaa irratti mo\'atan"}', '2025-12-19 09:54:23'),
(1, 1, '{"title":"የመንገድ ግንባታ ፕሮጀክት ጀምሯል","category":"መሠረተ ልማት","description":"በክፍለ ከተማው ምዕራባዊ ክፍል ውስጥ ብዙ የሚጠበቀው የመንገድ ግንባታ ፕሮጀክት ጀምሯል፣ ይህም የትራፊክ ፍሰትን እንደሚያሻሽል ይጠበቃል።","short_description":"የመሠረተ ልማት ማሻሻያዎች በከተማዋ ምዕራባዊ ክፍል ጀምረዋል"}', '{"title":"Piroojektii Gidduu Karaa Jalqabame","category":"Bu\'uura","description":"Piroojektii gidduu karaa kan seenaa magaalaa bahaatti baay\'ee eegamu jalqabame, dhaabbata fiigaa garaagarummaa taasisee bu\'aa fiigaa karaa fooyya\'isu.","short_description":"Fooyya\'insa bu\'uuraa seenaa magaalaa bahaatti jalqabame"}', '2025-12-19 09:54:23'),
(1, 1, '{"title":"አዲስ የነፍሳት አስተዳደር ተቋም ተጀመረ","category":"አካባቢ","description":"በማህበረሰባችን ውስጥ የአካባቢ መቆያነትን ለማበረታታት አዲስ የማደራጀት ፕሮግራም ተጀምሯል።","short_description":"አዲሱ የማደራጀት ፕሮግራም የአካባቢ መቆያነትን ያበረታታል"}', '{"title":"Kaayyoo Gidduu Saaphanaa Haaraan Jalqabame","category":"Naannoo","description":"Pirograamiin irra deddeebi\'ii haaraan hawaasa keenya keessatti taasisuu naannoo fooyya\'isuuf jalqabame.","short_description":"Pirograamiin irra deddeebi\'ii haaraa taasisuu naannoo gabbisuu dha"}', '2025-12-19 09:54:23'),
(1, 1, '{"title":"ልደታ አዲስ ዲጂታል አገልግሎት ማዕከል አስጀመረ","category":"ቴክኖሎጂ","description":"የልደታ ክፍለ ከተማ አስተዳደር እንደ መታወቂያ ሂደት፣ የግብር ጥያቄዎች እና የማህበረሰብ ማመልከቻዎች ያሉ አገልግሎቶችን ለማቅረብ የተነደፈ አዲስ ዲጂታል አገልግሎት ማዕከል አስጀምሯል።","short_description":"አዲሱ ዲጂታል አገልግሎት ማዕከል የከተማ አገልግሎቶችን ወደ ዜጎች ለማሻሻል ይረዳል"}', '{"title":"Lideta Giddugaleessa Tajaajilaa Dijitaalaa Haaraan Jalqabsiise","category":"Teknooloojii","description":"Bulchiinsa Lideta Sub-City giddugaleessa tajaajilaa dijitaalaa haaraan jalqabsiise, kan tajaajila akka hojii ID, gaafii kaffaltii, fi maddii hawaasaa akka tajaajilu qopheessee.","short_description":"Giddugaleessa tajaajilaa dijitaalaa haaraan dhaqqabaa tajaajila magaalaa jiraattotaaf fooyya\'isa"}', '2025-12-19 09:54:23'),
(1, 1, '{"title":"ክፍለ ከተማ ትልቅ የመንገድ ጥገና ሥራ ጀምሯል","category":"መሠረተ ልማት","description":"በክፍለ ከተማው ውስጥ በብዙ ወረዳዎች የመንገድ ቁልቁልትን ለመጠገን እና ደህንነትን ለማሻሻል ትልቅ የመንገድ ጥገና ተቋም ጀምሯል።","short_description":"የመንገድ ጥገና ፕሮጀክት በብዙ ሰፈራዎች ጀምሯል"}', '{"title":"Sub-City\'ichiin Hojii Guddaa Eegumsa Karaa Jalqabsiise","category":"Bu\'uura","description":"Kaayyoo guddaan eegumsa karaa jalqabame akka qullubbii karaa hojjechuufi nagaa seenaa magaalaa keessatti fooyya\'isuuf.","short_description":"Piroojektii eegumsa karaa seenaa magaalaa adda addaatti jalqabame"}', '2025-12-19 09:54:23'),
(1, 1, '{"title":"የአካባቢ ቤተ መጻሕፍት የወጣቶች ፕሮግራሞችን አስፋች","category":"ትምህርት","description":"የልደታ የህዝብ ቤተ መጻሕፍት የወጣቶች ፕሮግራሞቹን በአዲስ የማንበብ ክለቦች፣ ኮምፒውተር ዕውቀት ክፍሎች እና ቅዳሜ እና እሁድ የሥራ አውደ ማሰልጠኛዎች አስፋች።","short_description":"የወጣቶች ፕሮግራሞች በአዲስ የማንበብ እና ኮምፒውተር ክፍሎች ተሰፋፍተዋል"}', '{"title":"Mana Kitaaba Naannoo Daa\'imman Pirograamota Isaa Daddabsiise","category":"Barnoota","description":"Mana kitaaba ummataa Lidetan pirograamota daa\'immaa isaa daa\'immaa barreeffama haaraa, kuusaa kompiitaraa, fi waaksii guyyaa taphaataatiin daddabsiise.","short_description":"Pirograamota daa\'immaa daa\'immaa barreeffama haaraafi kuusaa kompiitaraa wajjin daddabsiifame"}', '2025-12-19 09:54:23'),
(1, 1, '{"title":"የማህበረሰብ አትክልት ማሳደግ ተቋም እያደገ ነው","category":"አካባቢ","description":"የማህበረሰብ አትክልት ፕሮጀክት እየተራመደ ሲሄድ የአካባቢ ነዋሪዎች አትክልቶችን፣ ቅጠላ ቅጠሎችን እና አበቦችን በጋራ የህዝብ ቦታዎች ውስጥ ለመትከል በፈቃደኝነት አገልግለዋል።","short_description":"ነዋሪዎች የማህበረሰብ አትክልት ቦታዎችን ለማስፋፋት በፈቃደኝነት አገልግልተዋል"}', '{"title":"Kaayyoo Biqilaa Hawaasaa Itti Fufuu Eegale","category":"Naannoo","description":"Piroojektii biqilaa hawaasaatiin itti fufuu eegale jiraattoota naannoo fedhii wajjin biqiloota, utubaa, fi abaaboo\'aa bakka ummataa waliin keessatti daddabsiisuuf hojjatan.","short_description":"Jiraattotni bakka biqilaa hawaasaa daddabsiisuuf fedhii wajjin hojjatan"}', '2025-12-19 09:54:23'),
(1, 1, '{"title":"ልደታ ዓመታዊ የንግድ መድረክ አካሄደ","category":"ንግድ","description":"ዓመታዊው የንግድ መድረክ ስለ ኢንቨስትመንት እድሎች እና ስለ አካባቢያዊ ኢኮኖሚያዊ እድገት ስትራቴጂዎች ለመወያየት ሰራተኞችን እና ባለሥልጣናትን አንድ ላይ አምጥቷል።","short_description":"የአካባቢ የንግድ መሪዎች ለእድገት ስትራቴጂዎች ለመወያየት ተሰብስበዋል"}', '{"title":"Lideta Murtii Daldalaa Waggaa Waggaa Taphate","category":"Daldala","description":"Murtiin daldalaa waggaa waggaa rakkoo daldalaa naannoo irratti mari\'achuuf hojjattootaa fi dhaabbileen walitti qaban, carraa daldalaa naannoo fi strateejii guddisaa dhaqaa naannoo irratti mari\'atan.","short_description":"Hoggantoota daldalaa naannoo wal ga\'ii strateejii guddisaa irratti mari\'achuuf walitti qaban"}', '2025-12-19 09:54:23'),
(1, 1, '{"title":"የህዝብ ፓርክ እድሳት ተጠናቋል","category":"ማህበረሰብ","description":"የማዕከላዊ የህዝብ ፓርክ እድሳት ተጠናቅቋል፣ ይህም አዳዲስ የመጫወቻ ቦታዎች፣ የእግረኛ መንገዶች እና የተሻሻለ መብራት ያካትታል።","short_description":"የማዕከላዊ የህዝብ ፓርክ ትልቅ እድሳት ተጠናቋል"}', '{"title":"Fuuldura Paarkii Ummataa Giddu Galeessaa Xumurame","category":"Hawaasaa","description":"Fuuldura paarkii ummataa giddu galeessaa xumurame, kan taphoota haaraa, karaa fiigaa, fi ifaa fooyya\'aa qabu.","short_description":"Fuuldura guddaa paarkii ummataa giddu galeessaa xumurame"}', '2025-12-19 09:54:23'),
(1, 1, '{"title":"የወጣቶች የስፖርት ሊግ ጀምሯል","category":"ስፖርት","description":"የወጣቶች የስፖርት ሊግ በይፋ ጀምሯል፣ ይህም በፊት ቦሎ፣ በአትሌቲክስ እና በሌሎች እንቅስቃሴዎች ተሳትፎን ለማበረታታት እና ጤናማ ኑሮን ለማስተዋወቅ ያበረታታል።","short_description":"አዲሱ የወጣቶች የስፖርት ወቅት በፊት ቦሎ እና በአትሌቲክስ ውድድር ጀምሯል"}', '{"title":"Liigii Ispoortii Daa\'immaa Jalqabame","category":"Isportii","description":"Liigiin ispoortii daa\'immaa milkaa\'inaan jalqabame, kubbaa miillaa, atileetikii, fi gochaalee biroo keessatti hirmaannaa dandeettii fayyaa qabu taasisuu dha.","short_description":"Tsiima ispoortii daa\'immaa haaraan kubbaa miillaa fi atileetikii wajjin jalqabame"}', '2025-12-19 09:54:23'),
(1, 1, '{"title":"ልደታ ክፍለ ከተማ ዋና የመንገድ መሠረተ ልማት ማሻሻያ ሥራ ጀምሯል","category":"መሠረተ ልማት","description":"ልደታ ክፍለ ከተማ አስተዳደር 12 ቁልፍ ኮሪደሮችን ያካተተ ሁሉን አቀፍ የመንገድ ማሻሻያ ፕሮጀክት በይፋ ጀምሯል። ፕሮጀክቱ ከ300,000 በላይ ለሚሆኑ ነዋሪዎች ረጅም ጊዜ ሲዘልቁ የቆዩ የትራንስፖርት ችግሮችን ለመፍታት ያለመ ነው። ፕሮጀክቱ የሚያካትተው፡ መንገድ ማስፋፋት፣ ዘመናዊ የፍሳሽ ዝርጋታ ማስቀመጥ፣ የእግረኛ መንገዶችና የጎዳና ብርሃን ማሻሻያ ነው። ፕሮጀክቱ በ18 ወር ውስጥ ሙሉ ለሙሉ እንዲጠናቀቅ ሲጠበቅ ደረጃ አንድ በሚቀጥሉ ስድስት ወሮች ለቀረቦ ይሆናል።","short_description":"ልደታ ክፍለ ከተማ አስተዳደር 12 ቁልፍ ኮሪደሮችን ያካተተ ሁሉን አቀፍ የመንገድ ማሻሻያ ፕሮጀክት በይፋ ጀምሯል።"}', '{"title":"Bulchiinsa Kutaa Magaalaa Lideta Hojii Fooyya\'insaa Daandii Gurguddaa Jalqabe","category":"Bu\'uura","description":"Bulchiinsi Kutaa Magaalaa Lideta pirojektii fooyya\'insaa daandii bal\'aa koriidaroota gurguddaa 12 hammate ifa baase. Pirojektiin kun jiraattoota 300,000 ol qaban rakkoo geejjibaa waggaa dheeraa ture furuu kaayyoo godhatee jira. Pirojektiin kun babal\'ina daandii, sirna dhangala\'aa ammayyaa, karaa miilaa fi guddina ifa daandii ni hammata. Pirojektiin guutummaatti baatii 18 keessatti xumuramuu eegama; marsaa jalqabaa baatii jaha dhufurratti kennama.","short_description":"Bulchiinsi Kutaa Magaalaa Lideta pirojektii fooyya\'insaa daandii bal\'aa koriidaroota 12 hammate ifa baase."}', '2026-08-23 10:05:39'),
(1, 1, '{"title":"የነፃ ጤና ምርመራ ዘመቻ ከ15,000 በላይ ነዋሪዎችን ደርሷል","category":"ጤና","description":"ልደታ ክፍለ ከተማ የጤና ጽ/ቤት ሦስት ሳምንት ነፃ ጤና ምርመራ ዘመቻ ስኬታማ ሆኖ ጨርሷል። ዘመቻው በ8 የጤና ጣቢያዎች ከ15,000 በላይ ነዋሪዎችን አገልግሏል። የስኳር ህመም፣ ደም ግፊት፣ ሳንባ ነቀርሳ እና የእናቶች ጤና ምርመራ ሰጥቷል። ከ2,300 በላይ ነዋሪዎች ወደ ክትትል ሕክምና ተላልፈዋል፣ 450 የደም ግፊት ህሙማን ተለይተዋল። ተመሳሳይ ዘመቻዎች በሩብ ዓመት ይካሄዳሉ።","short_description":"ልደታ ክፍለ ከተማ የጤና ጽ/ቤት ሦስት ሳምንት የሚቆይ የነፃ ጤና ምርመራ ዘመቻ ጨርሷል፤ ከ15,000 በላይ ነዋሪዎችን አገልግሏል።"}', '{"title":"Kaadhimamni Qorannoo Fayyaa Bilisaa Jiraattota 15,000 Ol Ga\'e","category":"Fayyaa","description":"Waajjirri Fayyaa Kutaa Magaalaa Lideta kaadhimama qorannoo fayyaa bilisaa torban sadii ture milkaa\'inaan xumure. Wiirtuu fayyaa hawaasaa 8 keessatti jiraattoota 15,000 ol tajaajileera. Qorannoo dhibee sookoraa, dhiibbaa dhiigaa, TB fi fayyaa haadholii ni hammate. Jiraattoota 2,300 ol wal\'aansa ittaansuuf ergaman; dhibee dhiibbaa dhiigaa hin beekkamne dura 450 adda bahan. Kaadhimamni fakkaataa rubu\'aa waggaatti gaggeeffama.","short_description":"Waajjirri Fayyaa Kutaa Magaalaa Lideta wiirtuu fayyaa 8 keessatti jiraattoota 15,000 ol tajaajile."}', '2026-08-23 10:05:39'),
(1, 1, '{"title":"ሦስት አዳዲስ የመጀመሪያ ደረጃ ትምህርት ቤቶች ተከፈቱ","category":"ትምህርት","description":"ሦስት አዲስ ሙሉ ዝግጅት ያላቸው የመጀመሪያ ደረጃ ትምህርት ቤቶች በልደታ ክፍለ ከተማ ምርቃ ሥሯ ተከናወነ። 2,400 አዲስ ተማሪ ስፍራዎችን ጨምሮ ለዓመታት የቀጠለ የክፍሎቹ ጠባቢነት ችግር ያቃልላሉ። እያንዳንዱ ትምህርት ቤት ዘመናዊ ክፍሎች፣ ኮምፒውተር ላቦ፣ ቤተ-መጻሕፍትና ስፖርት ሜዳ ይዟል። ከትምህርት ቤቶቹ ምርቃ በኋላ ክፍለ ከተማው የተማሪ ወደ ክፍሎቹ ጥምርታ ከ65፡1 ወደ 45፡1 ተሻሽሏል።","short_description":"ሦስት አዲስ ሙሉ ዝግጅት ያላቸው የመጀመሪያ ደረጃ ትምህርት ቤቶች ተምሮ 2,400 አዲስ ተማሪ ስፍራዎች ጨምረዋል።"}', '{"title":"Mana Barumsaa Sadarkaa Tokkoffaa Haaraa Sadii Baname","category":"Barnoota","description":"Mana barumsaa sadarkaa tokkoffaa haaraa guutuu qophaa\'e sadii kutaa magaalaa Lideta keessatti eebbifame. Teessoo barataa haaraa 2,400 dabaluun rakkoo xaxoo cufaa ta\'u waggaa dheeraa miidhaa barnootarratti gahe hir\'iseera. Manni barumsaa hundi kutaa ammayyaa, laaboraatoorii kompiyuutaraa, kuusaa kitaabaa fi dirree ispoortii qabaata. Kutaa magaalaa keessatti hir\'ina barattoota kutaadhaaf jiru 65:1 irraa 45:1 gahuu odeeffateera.","short_description":"Mana barumsaa sadarkaa tokkoffaa haaraa guutuu qophaa\'e sadii banameera; teessoo barataa haaraa 2,400 dabaluun rakkoo kutaa cufaa ta\'u hir\'ise."}', '2026-08-23 10:05:40'),
(1, 1, '{"title":"ልደታ ክፍለ ከተማ የቀበሌ ማህበረሰብ ምክክር መድረክ አዘጋጀ","category":"ክንውኖች","description":"ከ500 በላይ የማህበረሰብ መሪዎች፣ ወጣቶች ተወካዮች ና ነዋሪዎች ለሁለት ቀን ምክክር መድረክ ተሰበሰቡ። ምክክሩ ፓናል ውይይቶች፣ ሥራ ቡድኖች ና ክፍት ወለል ስብሰባዎች ያካትታል። ዋና ፍሬ ናቸው ካሏቸው ጉዳዮች አንዱ በሩብ ዓመት ተሰብስቦ ለአስተዳደሩ ምላሽ የሚሰጥ ቋሚ የማህበረሰብ አማካሪ ምክር ቤት ማቋቋም ነው። ሁሉም 10 ቀበሌዎች ተወካዮቻቸው ምክር ቤቱ ውስጥ ይኖሩዋቸዋል።","short_description":"ከ500 በላይ የማህበረሰብ መሪዎች፣ ወጣቶች ተወካዮችና ነዋሪዎች ለሁለት ቀን ምክክር መድረክ ተሳትፈዋል።"}', '{"title":"Kutaan Magaalaa Lideta Marii Hawaasaa Giddu-Galeessa Gaggeesse","category":"Taatee","description":"Hoggantoota hawaasaa fi jiraattoota kutaa magaalaa Lideta hundaa irraa dhufan 500 ol guyyaa lamaa mariif walitti qabaman. Marii kun marii garee paanelii, garee hojii fi taa\'ichi barcuma banaa ni hammate. Bu\'aa mariichaa ijoo keessaa tokko Koree Gorsa Hawaasaa Yeroo Hunda jiraatu hundeessuu waliigaluu ture. Kebeelee 10 hunda bakka bu\'oota qabaatu.","short_description":"Hoggantoota hawaasaa, bakka bu\'oota dargaggoota fi jiraattoota 500 ol marii guyyaa lama irratti argaman."}', '2026-08-23 10:05:40'),
(1, 1, '{"title":"አረንጓዴ ልደታ፡ 50,000 ዛፎች ተተክለዋል","category":"አካባቢ","description":"ልደታ ክፍለ ከተማ አስተዳደር \\"አረንጓዴ ልደታ\\" ቀጰ ሰርዷ ጀምሮ ከ3,000 በላይ ነዋሪዎች፣ ተማሪዎችና በጎ ፈቃደኞች ዓርብ ሳምንት ብቻ 50,000 ዛፎችን ፓርኮች፣ የጎዳና ዳርቻዎች ና ክፍት አረንጓዴ ቦታዎች ላይ ተክለዋል። ዋርካ፣ ቲዱ ና ፍሬ ሰጪ ዛፎች ዋና ዋና ዝርያዎቹ ናቸው። ለሚቀጥሉ ሁለት ዓመታት ክትትሎ ቡድኖች ወደ እያንዳንዱ ሥፍራ ይሰማሩ።","short_description":"ልደታ ክፍለ ከተማ \\"አረንጓዴ ልደታ\\" ቀጰ ሰርዷ ጀምሮ ነዋሪዎች እና በጎ ፈቃደኞች 50,000 ዛፎችን ተክለዋል።"}', '{"title":"Lideta Magariisaa: Muka 50,000 Dhaabame","category":"Naannoo","description":"Bulchiinsi Kutaa Magaalaa Lideta tarsiimoo naannoo seenaa qabeessa \\"Lideta Magariisaa\\" eebbise. Jiraattoota, barattootaa fi geengoo 3,000 ol hiriirsuun xandaa tokko qofaatti mooraa park, karaa fi bakka magariisaa banaarra muka 50,000 dhaabani. Warkaa, Tidhii fi muka firii kennuu kanneen filataman. Gaggeessitoota tajaajila kunuunsaa ganna lama dhufurratti kutaalee dhaabbii hunda irratti ramadama.","short_description":"Kutaan Magaalaa Lideta tarsiimoo \\"Lideta Magariisaa\\" eebbise; jiraattoota fi geengoo 3,000 ol hiriirsuun muka 50,000 dhaabe."}', '2026-08-23 10:05:43'),
(1, 1, '{"title":"ልደታ ክፍለ ከተማ ዲጂታሉ አገልግሎት ፖርታሉ ሥራ ጀምሯል","category":"ቴክኖሎጂ","description":"ልደታ ክፍለ ከተማ አስተዳደር ዲጂታሉ አገልግሎት ፖርታሉን ያስጀምሯ ሲሆን ነዋሪዎች 30 በላይ ማዘጋጃ አገልግሎቶችን ጽ/ቤቱን ሳይጎበኙ ኦንላይን ማግኘት ይችላሉ። ሥርዓቱ ዴስክቶፕና ሞባይሌ ተደራሽ ሆኖ በአማርኛ፣ ኦሮምኛ ና እንግሊዝኛ ያካሄዳል። አቅርቦ ያሉ አገልግሎቶች ናቸው፡ የንግድ ፈቃድ ታደሳ፣ የልደት ሰርቲፊኬት ና ቅሬታ ክትትሉ። ከ1,200 በላይ ነዋሪዎች ከጀምሮ በኋላ ባሉ ሳምንታት ምዝጋቧቸዋል።","short_description":"ነዋሪዎች አሁን ሰላሳ በላይ የማዘጋጃ አገልግሎቶችን ዲጂታሉ ፖርታሉ ጥቅም ላይ ሳያደርጉ ማድረግ ይችላሉ።"}', '{"title":"Portaalli Tajaajila Dijitaalaa Kutaa Magaalaa Lideta Hojii Jalqabe","category":"Teknooloojii","description":"Bulchiinsi Kutaa Magaalaa Lideta Portaalli Tajaajila Dijitaalaa eebbiseera. Jiraattonni tajaajila mootummaa 30 ol mana mootummaa deemuun alatti onlaayiniidhan argachuu ni danda\'u. Sirni kun kompiyuutaraa fi moobayiliidhan dhaqqabamuu danda\'uu Afaan Amaaraa, Afaan Oromoo fi Afaan Ingiliiziitiin ni hojjata. Tajaajilli haaromsa hayyama daldalaa, ragaa dhalootaa fi iyyannoo komii ni hammata. Jiraattoota 1,200 ol torbana jalqabaa keessatti galmeeffaman.","short_description":"Jiraattonni tajaajila mootummaa 30 ol portaalli dijitaalaa haaraa fayyadamuudhaan mana mootummaa dhaquu malee argachuu danda\'u."}', '2026-08-23 10:05:44'),
(1, 1, '{"title":"ክፍለ ከተማ አስተዳደሩ ህገ-ወጥ ሕንፃ ግንባታ ላይ ጠንከረ","category":"ደህንነት","description":"ልደታ ክፍለ ከተማ አስተዳደር ህገ-ወጥ ሕንፃዎችን ለማፍረስ ዘጠኝ ሳምንት ዘመቻ ካካሄደ 47 ህገ-ወጥ ሕንፃ ፈርሶ 120 ባለ ንብረቶት ማስጠንቀቂያ ተሰጣቸው። ሕንፃዎቹ ዋና ዋናዎቹ ናቸው፡ ፈቃድ ሳይወሰዱ ያሳቆሩ ሕንፃዎችና የሕዝብ ቦታ ወረራዎች። ሕጋዊ ፈቃድ ከማውጣት ሳይጀምሩ ሕንፃ ለሚሰሩ ሁሉ ነፃ ምክር ይሰጣል።","short_description":"ልደታ ክፍለ ከተማ 47 ህገ-ወጥ ሕንፃዎችን አፍርሶ 120 ባለ ንብረቶችን ማስጠንቀቂያ ሰጠ።"}', '{"title":"Bulchiinsi Kutaa Magaalaa Ijaarsaa Seeraan Alaa Irratti Jabaate","category":"Nagaa","description":"Tarkaanfii murteessaa ta\'een Bulchiinsi Kutaa Magaalaa Lideta wiirtuu torban jahaa ijaarsaa seeraan alaa 47 diigee abbaa qabeenya dabalataa 120 tti beeksisa ergite. Ijaarsaaleen kun carraa daandii uummataa seenuun dhuunfataman, mana hayyama malee ijaaraman ni hammatu. Abbaa qabeenyaa tarree kenname keessatti ijaarsa seeraan alaa of-danda\'an diigan adabbii dabalataa hin argatan.","short_description":"Kutaan Magaalaa Lideta ijaarsa seeraan alaa 47 diigee, abbaa qabeenya 120 tti ajaja ergite."}', '2026-08-23 10:05:44'),
(1, 1, '{"title":"የወጣቶች ክህሎት ማሰልጠኛ ማዕከል 800 ወጣቶችን ምዝጋቧል","category":"ትምህርት","description":"ልደታ ክፍለ ከተማ ወጣቶችና ስፖርት ጽ/ቤት ከ18 እስከ 35 ዓመት 800 ወጣቶችን ቅርብ ሙያ ክህሎት ሥልጠናዎች ምዝጋቧቸዋል። ሥልጠናው ኢንፎርሜሽን ቴክኖሎጂ፣ ስፌት ፋሽን ዲዛይን ና ሸክምና ምሰሶ ሥራ ያካትታል። ፕሮግራሙ ምሩቃን ለ70% ሥራ ያቀርቧቸዋል። ቀጣዩ ዙር ምዝገባ ቅድሚያ ለሴቶች፣ አካል ጉዳተኞችና ዝቅተኛ ቤተሰቦቻቸው ሕፃናት ተሰጥቷቸዋል።","short_description":"ልደታ ክፍለ ከተማ ወጣቶች ጽ/ቤት 800 ወጣቶችን የሙያ ክህሎት ሥልጠናዎች ምዝጋቧቸዋል።"}', '{"title":"Wiirtuu Leenjii Dandeettii Dargaggoota 800 Galmeesse","category":"Barnoota","description":"Waajjirri Dargaggoota fi Ispoortii Kutaa Magaalaa Lideta dargaggoo waggaa 18 hanga 35 ta\'an 800 sagantaa leenjii dandeettii ogummaa haaraadhaaf galmeesseera. Leenjiin IT, uffata ho\'isuu fi ijaarsa ni hammata. Sagantaan kana dura dhibbeentaa 70 ol hojii argatan. Galmeessa wiirtuu itti aanuuf dursa dubartootaa, qaamni miidhameefi maatii galii gadi-aanaa qabaniif kenname.","short_description":"Waajjirri Dargaggoota Kutaa Magaalaa Lideta dargaggoo 800 sagantaa leenjii dandeettii ogummaa haaraadhaf galmeesse."}', '2026-08-23 10:05:45'),
(1, 1, '{"title":"ታደሰው ልደታ ዋናው ገበያ ለነጋዴዎችና ሕዝብ ተከፈተ","category":"መሠረተ ልማት","description":"14 ወር ከፍተኛ ግንባታ ካለቀ በኋላ ሙሉ ታደሰው ልደታ ዋናው ገበያ ለነጋዴዎችና ሕዝብ ተከፈተ። ፕሮጀክቱ ጠባቡ ጥፍ ባዩ ገበያ ከ800 ቋሚ ሱቆቹ ቁጥር ያለ ዘመናዊ ቦታ ወደ ቀይሮታል። ፍሬ ጥቁር ወርቅ፣ ለብሰው ኢሌክትሮኒክስ ና ምግብ አገልግሎት ልዩ ቦታዎቹ ናቸው። ዋናዋ ቆሻሻ አወጋገድ ሥርዓት፣ ሳኒቴሽን ሕዳጎቻ ና CCTV ክትትሉ ፍሬዎቹ ናቸው።","short_description":"14 ወር ግንባታ ካለቀ በኋላ ሙሉ ታደሰው ልደታ ዋናው ገበያ ዘመናዊ ሱቆቹ ሳኒቴሽን ና የእሳት ደህንነት ሥርዓቶቹ ጋር ተከፈተ።"}', '{"title":"Gabatee Giddugaleessa Lideta Haaromsame Daldaltoota fi Uummataaf Baname","category":"Bu\'uura","description":"Gabatee Giddugaleessa Lideta erga ijaarsi cimaa baatii 14 erga xumuramee booda daldaltoota fi uummataaf itti banameera. Pirojektiin haaromsaa gabatee cufaa mancaa\'aa ture gara wiirtuu daldala ammayyaa teessoo bantii 800 ol qabu jijjiire. Naannoo addaa oomisha qilleensa qabate, uffata, elektirooniksi fi tajaajila nyaataaf; sirna bulchiinsa qotiyyoo fi to\'annoo CCTV ni hammatu.","short_description":"Gabatee Giddugaleessa Lideta baatii 14 ijaaramee guutummaatti haaromsamee bantii ammayyaa waliin banameera."}', '2026-08-23 10:05:45'),
(1, 1, '{"title":"ልደታ ክፍለ ከተማ ለሕዝብ አገልግሎት ዕጽዋ ሽልማት ተቀበለ","category":"ክንውኖች","description":"ልደታ ክፍለ ከተማ አስተዳደር ለሁለተኛ ተከታይ ዓመት የአዲስ አበባ ከተማ አስተዳደር ምርጥ ሕዝብ አገልግሎት ሽልማት ተቀበለ። ሽልማቱ ሕዝብ አገልግሎት ጥራት፣ ዜጎች እርካታ ና አስተዳደር ግልፅነት ወቅታዊ አፈፃፀምን ይሸልማል። ሽልሙ ዓመታዊ ጉባኤ ላይ ቀርቦ ልደታ የጉዳይ ጊዜ 42% ቀንሷል፣ ዜጎች ዕርካታ 87% ደርሷል ና ዲጂታሉ ቅሬታ ምስሪት ሙሉ ቀርቦ ሥራ ላይ ሆኗ።","short_description":"ልደታ ክፍለ ከተማ አስተዳደር ለሁለተኛ ተከታይ ዓመት የአዲስ አበባ ምርጥ ሕዝብ አገልግሎት ሽልማት ተቀበለ።"}', '{"title":"Kutaan Magaalaa Lideta Badhaasa Qulqullina Tajaajila Uummataa Fudhate","category":"Taatee","description":"Bulchiinsi Kutaa Magaalaa Lideta Badhaasa Qulqullina Tajaajila Uummataa Bulchiinsa Magaalaa Finfinnee waggaa lammataaf wal-duraa duubaan fudhate. Tajaajila qulqullina, gammachuu lammii fi iftoominaa bulchiinsaatiin raawwii ol\'aanaa agarsiise. Badhaasni milkaa\'ina Lideta eeruun: yeroo eeggannaa tajaajilaa giddu-galeessaa dhibbeentaa 42tiin hir\'isuu, lammiidhaan maxxanfame dhibbeentaa 87 ta\'uun, fi sirna bulchiinsa komii dijitaalaa guutummaatti hojjetu hojiirra oolchuun.","short_description":"Bulchiinsi Kutaa Magaalaa Lideta Badhaasa Qulqullina Tajaajila Uummataa waggaa lammataaf wal-duraa duubaan fudhate."}', '2026-08-23 10:05:47'),
(1, 1, '{"title":"ልደታ ክፍለ ከተማ ዋና የመንገድ መሠረተ ልማት ማሻሻያ ሥራ ጀምሯል","category":"መሠረተ ልማት","description":"ልደታ ክፍለ ከተማ አስተዳደር 12 ቁልፍ ኮሪደሮችን ያካተተ ሁሉን አቀፍ የመንገድ ማሻሻያ ፕሮጀክት በይፋ ጀምሯል። ፕሮጀክቱ ከ300,000 በላይ ለሚሆኑ ነዋሪዎች ረጅም ጊዜ ሲዘልቁ የቆዩ የትራንስፖርት ችግሮችን ለመፍታት ያለመ ነው። ፕሮጀክቱ የሚያካትተው፡ መንገድ ማስፋፋት፣ ዘመናዊ የፍሳሽ ዝርጋታ ማስቀመጥ፣ የእግረኛ መንገዶችና የጎዳና ብርሃን ማሻሻያ ነው። ፕሮጀክቱ በ18 ወር ውስጥ ሙሉ ለሙሉ እንዲጠናቀቅ ሲጠበቅ ደረጃ አንድ በሚቀጥሉ ስድስት ወሮች ለቀረቦ ይሆናል።","short_description":"ልደታ ክፍለ ከተማ አስተዳደር 12 ቁልፍ ኮሪደሮችን ያካተተ ሁሉን አቀፍ የመንገድ ማሻሻያ ፕሮጀክት በይፋ ጀምሯል።"}', '{"title":"Bulchiinsa Kutaa Magaalaa Lideta Hojii Fooyya\'insaa Daandii Gurguddaa Jalqabe","category":"Bu\'uura","description":"Bulchiinsi Kutaa Magaalaa Lideta pirojektii fooyya\'insaa daandii bal\'aa koriidaroota gurguddaa 12 hammate ifa baase. Pirojektiin kun jiraattoota 300,000 ol qaban rakkoo geejjibaa waggaa dheeraa ture furuu kaayyoo godhatee jira. Pirojektiin kun babal\'ina daandii, sirna dhangala\'aa ammayyaa, karaa miilaa fi guddina ifa daandii ni hammata. Pirojektiin guutummaatti baatii 18 keessatti xumuramuu eegama; marsaa jalqabaa baatii jaha dhufurratti kennama.","short_description":"Bulchiinsi Kutaa Magaalaa Lideta pirojektii fooyya\'insaa daandii bal\'aa koriidaroota 12 hammate ifa baase."}', '2026-08-23 11:30:12'),
(1, 1, '{"title":"የነፃ ጤና ምርመራ ዘመቻ ከ15,000 በላይ ነዋሪዎችን ደርሷል","category":"ጤና","description":"ልደታ ክፍለ ከተማ የጤና ጽ/ቤት ሦስት ሳምንት ነፃ ጤና ምርመራ ዘመቻ ስኬታማ ሆኖ ጨርሷል። ዘመቻው በ8 የጤና ጣቢያዎች ከ15,000 በላይ ነዋሪዎችን አገልግሏል። የስኳር ህመም፣ ደም ግፊት፣ ሳንባ ነቀርሳ እና የእናቶች ጤና ምርመራ ሰጥቷል። ከ2,300 በላይ ነዋሪዎች ወደ ክትትል ሕክምና ተላልፈዋል፣ 450 የደም ግፊት ህሙማን ተለይተዋল። ተመሳሳይ ዘመቻዎች በሩብ ዓመት ይካሄዳሉ።","short_description":"ልደታ ክፍለ ከተማ የጤና ጽ/ቤት ሦስት ሳምንት የሚቆይ የነፃ ጤና ምርመራ ዘመቻ ጨርሷል፤ ከ15,000 በላይ ነዋሪዎችን አገልግሏል።"}', '{"title":"Kaadhimamni Qorannoo Fayyaa Bilisaa Jiraattota 15,000 Ol Ga\'e","category":"Fayyaa","description":"Waajjirri Fayyaa Kutaa Magaalaa Lideta kaadhimama qorannoo fayyaa bilisaa torban sadii ture milkaa\'inaan xumure. Wiirtuu fayyaa hawaasaa 8 keessatti jiraattoota 15,000 ol tajaajileera. Qorannoo dhibee sookoraa, dhiibbaa dhiigaa, TB fi fayyaa haadholii ni hammate. Jiraattoota 2,300 ol wal\'aansa ittaansuuf ergaman; dhibee dhiibbaa dhiigaa hin beekkamne dura 450 adda bahan. Kaadhimamni fakkaataa rubu\'aa waggaatti gaggeeffama.","short_description":"Waajjirri Fayyaa Kutaa Magaalaa Lideta wiirtuu fayyaa 8 keessatti jiraattoota 15,000 ol tajaajile."}', '2026-08-23 11:30:13'),
(1, 1, '{"title":"ሦስት አዳዲስ የመጀመሪያ ደረጃ ትምህርት ቤቶች ተከፈቱ","category":"ትምህርት","description":"ሦስት አዲስ ሙሉ ዝግጅት ያላቸው የመጀመሪያ ደረጃ ትምህርት ቤቶች በልደታ ክፍለ ከተማ ምርቃ ሥሯ ተከናወነ። 2,400 አዲስ ተማሪ ስፍራዎችን ጨምሮ ለዓመታት የቀጠለ የክፍሎቹ ጠባቢነት ችግር ያቃልላሉ። እያንዳንዱ ትምህርት ቤት ዘመናዊ ክፍሎች፣ ኮምፒውተር ላቦ፣ ቤተ-መጻሕፍትና ስፖርት ሜዳ ይዟል። ከትምህርት ቤቶቹ ምርቃ በኋላ ክፍለ ከተማው የተማሪ ወደ ክፍሎቹ ጥምርታ ከ65፡1 ወደ 45፡1 ተሻሽሏል።","short_description":"ሦስት አዲስ ሙሉ ዝግጅት ያላቸው የመጀመሪያ ደረጃ ትምህርት ቤቶች ተምሮ 2,400 አዲስ ተማሪ ስፍራዎች ጨምረዋል።"}', '{"title":"Mana Barumsaa Sadarkaa Tokkoffaa Haaraa Sadii Baname","category":"Barnoota","description":"Mana barumsaa sadarkaa tokkoffaa haaraa guutuu qophaa\'e sadii kutaa magaalaa Lideta keessatti eebbifame. Teessoo barataa haaraa 2,400 dabaluun rakkoo xaxoo cufaa ta\'u waggaa dheeraa miidhaa barnootarratti gahe hir\'iseera. Manni barumsaa hundi kutaa ammayyaa, laaboraatoorii kompiyuutaraa, kuusaa kitaabaa fi dirree ispoortii qabaata. Kutaa magaalaa keessatti hir\'ina barattoota kutaadhaaf jiru 65:1 irraa 45:1 gahuu odeeffateera.","short_description":"Mana barumsaa sadarkaa tokkoffaa haaraa guutuu qophaa\'e sadii banameera; teessoo barataa haaraa 2,400 dabaluun rakkoo kutaa cufaa ta\'u hir\'ise."}', '2026-08-23 11:30:14'),
(1, 1, '{"title":"ልደታ ክፍለ ከተማ የቀበሌ ማህበረሰብ ምክክር መድረክ አዘጋጀ","category":"ክንውኖች","description":"ከ500 በላይ የማህበረሰብ መሪዎች፣ ወጣቶች ተወካዮች ና ነዋሪዎች ለሁለት ቀን ምክክር መድረክ ተሰበሰቡ። ምክክሩ ፓናል ውይይቶች፣ ሥራ ቡድኖች ና ክፍት ወለል ስብሰባዎች ያካትታል። ዋና ፍሬ ናቸው ካሏቸው ጉዳዮች አንዱ በሩብ ዓመት ተሰብስቦ ለአስተዳደሩ ምላሽ የሚሰጥ ቋሚ የማህበረሰብ አማካሪ ምክር ቤት ማቋቋም ነው። ሁሉም 10 ቀበሌዎች ተወካዮቻቸው ምክር ቤቱ ውስጥ ይኖሩዋቸዋል።","short_description":"ከ500 በላይ የማህበረሰብ መሪዎች፣ ወጣቶች ተወካዮችና ነዋሪዎች ለሁለት ቀን ምክክር መድረክ ተሳትፈዋል።"}', '{"title":"Kutaan Magaalaa Lideta Marii Hawaasaa Giddu-Galeessa Gaggeesse","category":"Taatee","description":"Hoggantoota hawaasaa fi jiraattoota kutaa magaalaa Lideta hundaa irraa dhufan 500 ol guyyaa lamaa mariif walitti qabaman. Marii kun marii garee paanelii, garee hojii fi taa\'ichi barcuma banaa ni hammate. Bu\'aa mariichaa ijoo keessaa tokko Koree Gorsa Hawaasaa Yeroo Hunda jiraatu hundeessuu waliigaluu ture. Kebeelee 10 hunda bakka bu\'oota qabaatu.","short_description":"Hoggantoota hawaasaa, bakka bu\'oota dargaggoota fi jiraattoota 500 ol marii guyyaa lama irratti argaman."}', '2026-08-23 11:30:15'),
(1, 1, '{"title":"አረንጓዴ ልደታ፡ 50,000 ዛፎች ተተክለዋል","category":"አካባቢ","description":"ልደታ ክፍለ ከተማ አስተዳደር \\"አረንጓዴ ልደታ\\" ቀጰ ሰርዷ ጀምሮ ከ3,000 በላይ ነዋሪዎች፣ ተማሪዎችና በጎ ፈቃደኞች ዓርብ ሳምንት ብቻ 50,000 ዛፎችን ፓርኮች፣ የጎዳና ዳርቻዎች ና ክፍት አረንጓዴ ቦታዎች ላይ ተክለዋል። ዋርካ፣ ቲዱ ና ፍሬ ሰጪ ዛፎች ዋና ዋና ዝርያዎቹ ናቸው። ለሚቀጥሉ ሁለት ዓመታት ክትትሎ ቡድኖች ወደ እያንዳንዱ ሥፍራ ይሰማሩ።","short_description":"ልደታ ክፍለ ከተማ \\"አረንጓዴ ልደታ\\" ቀጰ ሰርዷ ጀምሮ ነዋሪዎች እና በጎ ፈቃደኞች 50,000 ዛፎችን ተክለዋል።"}', '{"title":"Lideta Magariisaa: Muka 50,000 Dhaabame","category":"Naannoo","description":"Bulchiinsi Kutaa Magaalaa Lideta tarsiimoo naannoo seenaa qabeessa \\"Lideta Magariisaa\\" eebbise. Jiraattoota, barattootaa fi geengoo 3,000 ol hiriirsuun xandaa tokko qofaatti mooraa park, karaa fi bakka magariisaa banaarra muka 50,000 dhaabani. Warkaa, Tidhii fi muka firii kennuu kanneen filataman. Gaggeessitoota tajaajila kunuunsaa ganna lama dhufurratti kutaalee dhaabbii hunda irratti ramadama.","short_description":"Kutaan Magaalaa Lideta tarsiimoo \\"Lideta Magariisaa\\" eebbise; jiraattoota fi geengoo 3,000 ol hiriirsuun muka 50,000 dhaabe."}', '2026-08-23 11:30:18'),
(1, 1, '{"title":"ልደታ ክፍለ ከተማ ዲጂታሉ አገልግሎት ፖርታሉ ሥራ ጀምሯል","category":"ቴክኖሎጂ","description":"ልደታ ክፍለ ከተማ አስተዳደር ዲጂታሉ አገልግሎት ፖርታሉን ያስጀምሯ ሲሆን ነዋሪዎች 30 በላይ ማዘጋጃ አገልግሎቶችን ጽ/ቤቱን ሳይጎበኙ ኦንላይን ማግኘት ይችላሉ። ሥርዓቱ ዴስክቶፕና ሞባይሌ ተደራሽ ሆኖ በአማርኛ፣ ኦሮምኛ ና እንግሊዝኛ ያካሄዳል። አቅርቦ ያሉ አገልግሎቶች ናቸው፡ የንግድ ፈቃድ ታደሳ፣ የልደት ሰርቲፊኬት ና ቅሬታ ክትትሉ። ከ1,200 በላይ ነዋሪዎች ከጀምሮ በኋላ ባሉ ሳምንታት ምዝጋቧቸዋል።","short_description":"ነዋሪዎች አሁን ሰላሳ በላይ የማዘጋጃ አገልግሎቶችን ዲጂታሉ ፖርታሉ ጥቅም ላይ ሳያደርጉ ማድረግ ይችላሉ።"}', '{"title":"Portaalli Tajaajila Dijitaalaa Kutaa Magaalaa Lideta Hojii Jalqabe","category":"Teknooloojii","description":"Bulchiinsi Kutaa Magaalaa Lideta Portaalli Tajaajila Dijitaalaa eebbiseera. Jiraattonni tajaajila mootummaa 30 ol mana mootummaa deemuun alatti onlaayiniidhan argachuu ni danda\'u. Sirni kun kompiyuutaraa fi moobayiliidhan dhaqqabamuu danda\'uu Afaan Amaaraa, Afaan Oromoo fi Afaan Ingiliiziitiin ni hojjata. Tajaajilli haaromsa hayyama daldalaa, ragaa dhalootaa fi iyyannoo komii ni hammata. Jiraattoota 1,200 ol torbana jalqabaa keessatti galmeeffaman.","short_description":"Jiraattonni tajaajila mootummaa 30 ol portaalli dijitaalaa haaraa fayyadamuudhaan mana mootummaa dhaquu malee argachuu danda\'u."}', '2026-08-23 11:30:19'),
(1, 1, '{"title":"ክፍለ ከተማ አስተዳደሩ ህገ-ወጥ ሕንፃ ግንባታ ላይ ጠንከረ","category":"ደህንነት","description":"ልደታ ክፍለ ከተማ አስተዳደር ህገ-ወጥ ሕንፃዎችን ለማፍረስ ዘጠኝ ሳምንት ዘመቻ ካካሄደ 47 ህገ-ወጥ ሕንፃ ፈርሶ 120 ባለ ንብረቶት ማስጠንቀቂያ ተሰጣቸው። ሕንፃዎቹ ዋና ዋናዎቹ ናቸው፡ ፈቃድ ሳይወሰዱ ያሳቆሩ ሕንፃዎችና የሕዝብ ቦታ ወረራዎች። ሕጋዊ ፈቃድ ከማውጣት ሳይጀምሩ ሕንፃ ለሚሰሩ ሁሉ ነፃ ምክር ይሰጣል።","short_description":"ልደታ ክፍለ ከተማ 47 ህገ-ወጥ ሕንፃዎችን አፍርሶ 120 ባለ ንብረቶችን ማስጠንቀቂያ ሰጠ።"}', '{"title":"Bulchiinsi Kutaa Magaalaa Ijaarsaa Seeraan Alaa Irratti Jabaate","category":"Nagaa","description":"Tarkaanfii murteessaa ta\'een Bulchiinsi Kutaa Magaalaa Lideta wiirtuu torban jahaa ijaarsaa seeraan alaa 47 diigee abbaa qabeenya dabalataa 120 tti beeksisa ergite. Ijaarsaaleen kun carraa daandii uummataa seenuun dhuunfataman, mana hayyama malee ijaaraman ni hammatu. Abbaa qabeenyaa tarree kenname keessatti ijaarsa seeraan alaa of-danda\'an diigan adabbii dabalataa hin argatan.","short_description":"Kutaan Magaalaa Lideta ijaarsa seeraan alaa 47 diigee, abbaa qabeenya 120 tti ajaja ergite."}', '2026-08-23 11:30:20'),
(1, 1, '{"title":"የወጣቶች ክህሎት ማሰልጠኛ ማዕከል 800 ወጣቶችን ምዝጋቧል","category":"ትምህርት","description":"ልደታ ክፍለ ከተማ ወጣቶችና ስፖርት ጽ/ቤት ከ18 እስከ 35 ዓመት 800 ወጣቶችን ቅርብ ሙያ ክህሎት ሥልጠናዎች ምዝጋቧቸዋል። ሥልጠናው ኢንፎርሜሽን ቴክኖሎጂ፣ ስፌት ፋሽን ዲዛይን ና ሸክምና ምሰሶ ሥራ ያካትታል። ፕሮግራሙ ምሩቃን ለ70% ሥራ ያቀርቧቸዋል። ቀጣዩ ዙር ምዝገባ ቅድሚያ ለሴቶች፣ አካል ጉዳተኞችና ዝቅተኛ ቤተሰቦቻቸው ሕፃናት ተሰጥቷቸዋል።","short_description":"ልደታ ክፍለ ከተማ ወጣቶች ጽ/ቤት 800 ወጣቶችን የሙያ ክህሎት ሥልጠናዎች ምዝጋቧቸዋል።"}', '{"title":"Wiirtuu Leenjii Dandeettii Dargaggoota 800 Galmeesse","category":"Barnoota","description":"Waajjirri Dargaggoota fi Ispoortii Kutaa Magaalaa Lideta dargaggoo waggaa 18 hanga 35 ta\'an 800 sagantaa leenjii dandeettii ogummaa haaraadhaaf galmeesseera. Leenjiin IT, uffata ho\'isuu fi ijaarsa ni hammata. Sagantaan kana dura dhibbeentaa 70 ol hojii argatan. Galmeessa wiirtuu itti aanuuf dursa dubartootaa, qaamni miidhameefi maatii galii gadi-aanaa qabaniif kenname.","short_description":"Waajjirri Dargaggoota Kutaa Magaalaa Lideta dargaggoo 800 sagantaa leenjii dandeettii ogummaa haaraadhaf galmeesse."}', '2026-08-23 11:30:20'),
(1, 1, '{"title":"ታደሰው ልደታ ዋናው ገበያ ለነጋዴዎችና ሕዝብ ተከፈተ","category":"መሠረተ ልማት","description":"14 ወር ከፍተኛ ግንባታ ካለቀ በኋላ ሙሉ ታደሰው ልደታ ዋናው ገበያ ለነጋዴዎችና ሕዝብ ተከፈተ። ፕሮጀክቱ ጠባቡ ጥፍ ባዩ ገበያ ከ800 ቋሚ ሱቆቹ ቁጥር ያለ ዘመናዊ ቦታ ወደ ቀይሮታል። ፍሬ ጥቁር ወርቅ፣ ለብሰው ኢሌክትሮኒክስ ና ምግብ አገልግሎት ልዩ ቦታዎቹ ናቸው። ዋናዋ ቆሻሻ አወጋገድ ሥርዓት፣ ሳኒቴሽን ሕዳጎቻ ና CCTV ክትትሉ ፍሬዎቹ ናቸው።","short_description":"14 ወር ግንባታ ካለቀ በኋላ ሙሉ ታደሰው ልደታ ዋናው ገበያ ዘመናዊ ሱቆቹ ሳኒቴሽን ና የእሳት ደህንነት ሥርዓቶቹ ጋር ተከፈተ።"}', '{"title":"Gabatee Giddugaleessa Lideta Haaromsame Daldaltoota fi Uummataaf Baname","category":"Bu\'uura","description":"Gabatee Giddugaleessa Lideta erga ijaarsi cimaa baatii 14 erga xumuramee booda daldaltoota fi uummataaf itti banameera. Pirojektiin haaromsaa gabatee cufaa mancaa\'aa ture gara wiirtuu daldala ammayyaa teessoo bantii 800 ol qabu jijjiire. Naannoo addaa oomisha qilleensa qabate, uffata, elektirooniksi fi tajaajila nyaataaf; sirna bulchiinsa qotiyyoo fi to\'annoo CCTV ni hammatu.","short_description":"Gabatee Giddugaleessa Lideta baatii 14 ijaaramee guutummaatti haaromsamee bantii ammayyaa waliin banameera."}', '2026-08-23 11:30:21'),
(1, 1, '{"title":"ልደታ ክፍለ ከተማ ለሕዝብ አገልግሎት ዕጽዋ ሽልማት ተቀበለ","category":"ክንውኖች","description":"ልደታ ክፍለ ከተማ አስተዳደር ለሁለተኛ ተከታይ ዓመት የአዲስ አበባ ከተማ አስተዳደር ምርጥ ሕዝብ አገልግሎት ሽልማት ተቀበለ። ሽልማቱ ሕዝብ አገልግሎት ጥራት፣ ዜጎች እርካታ ና አስተዳደር ግልፅነት ወቅታዊ አፈፃፀምን ይሸልማል። ሽልሙ ዓመታዊ ጉባኤ ላይ ቀርቦ ልደታ የጉዳይ ጊዜ 42% ቀንሷል፣ ዜጎች ዕርካታ 87% ደርሷል ና ዲጂታሉ ቅሬታ ምስሪት ሙሉ ቀርቦ ሥራ ላይ ሆኗ።","short_description":"ልደታ ክፍለ ከተማ አስተዳደር ለሁለተኛ ተከታይ ዓመት የአዲስ አበባ ምርጥ ሕዝብ አገልግሎት ሽልማት ተቀበለ።"}', '{"title":"Kutaan Magaalaa Lideta Badhaasa Qulqullina Tajaajila Uummataa Fudhate","category":"Taatee","description":"Bulchiinsi Kutaa Magaalaa Lideta Badhaasa Qulqullina Tajaajila Uummataa Bulchiinsa Magaalaa Finfinnee waggaa lammataaf wal-duraa duubaan fudhate. Tajaajila qulqullina, gammachuu lammii fi iftoominaa bulchiinsaatiin raawwii ol\'aanaa agarsiise. Badhaasni milkaa\'ina Lideta eeruun: yeroo eeggannaa tajaajilaa giddu-galeessaa dhibbeentaa 42tiin hir\'isuu, lammiidhaan maxxanfame dhibbeentaa 87 ta\'uun, fi sirna bulchiinsa komii dijitaalaa guutummaatti hojjetu hojiirra oolchuun.","short_description":"Bulchiinsi Kutaa Magaalaa Lideta Badhaasa Qulqullina Tajaajila Uummataa waggaa lammataaf wal-duraa duubaan fudhate."}', '2026-08-23 11:30:22');
