INSERT INTO `vacancies` (`id`, `title`, `short_description`, `description`, `location`, `salary`, `type`, `category`, `skills`, `responsibilities`, `qualifications`, `start_date`, `end_date`, `created_at`, `updated_at`) VALUES
(1, 'Administrative Assistant', 'Coordinate daily office operations and provide comprehensive administrative support to department heads. Manage correspondence and schedules.', 'As an Administrative Assistant at Lideta Subcity Government Office, you will be responsible for providing comprehensive administrative support to department heads and ensuring smooth daily operations across all departments. Your role will involve managing correspondence, coordinating meetings and appointments, maintaining organized filing systems, and serving as the primary point of contact for internal and external stakeholders. You will work closely with senior officials to prepare reports, presentations, and official documents while ensuring compliance with government protocols and procedures. This position requires exceptional organizational skills, attention to detail, and the ability to handle multiple priorities in a fast-paced government environment. You will also be responsible for managing office supplies, coordinating logistics for meetings and events, and maintaining confidentiality of sensitive government information.', 'Lideta Subcity Office', '42000', 'fulltime', 'Administration', '["document_management","time_management","communication_skills"]', '["Manage and coordinate calendars, appointments, and meetings for department heads, ensuring optimal scheduling and time management across multiple priorities while anticipating conflicts and proposing solutions","Prepare, proofread, and format official documents, reports, presentations, and correspondence according to government standards and protocols, ensuring accuracy, consistency, and professional presentation","Maintain comprehensive electronic and physical filing systems for administrative documents, correspondence, and records, implementing efficient retrieval systems and ensuring compliance with government record-keeping regulations","Serve as primary liaison between department heads and other government offices, community organizations, and the public, handling inquiries professionally and directing them to appropriate personnel","Coordinate logistics for meetings, conferences, and official events including venue arrangements, equipment setup, catering, and preparation of meeting materials and agendas","Manage office supplies inventory, procurement processes, and equipment maintenance, anticipating needs and ensuring continuous availability of essential resources","Process and track official correspondence, memos, and communications, ensuring timely distribution and proper documentation of all official communications","Assist in budget preparation and monitoring by tracking expenditures, processing invoices, and maintaining financial records for departmental operations"]', '["Minimum of Diploma in Office Management, Business Administration, or related field from an accredited institution with demonstrated coursework in administrative procedures and office technology","At least two years of progressive administrative support experience in government offices, corporate environments, or large organizations with proven ability to handle sensitive information confidentially","Advanced proficiency in Microsoft Office Suite (Word, Excel, PowerPoint, Outlook) and government document management systems with ability to create complex documents, spreadsheets, and presentations","Exceptional written and verbal communication skills in Amharic and English with demonstrated ability to draft professional correspondence and communicate effectively with diverse stakeholders","Proven organizational and time management abilities with capacity to prioritize multiple tasks, meet deadlines, and maintain attention to detail in high-pressure situations","Strong interpersonal skills with ability to build positive working relationships with officials, colleagues, and community members while maintaining professional boundaries","Knowledge of government administrative procedures, document handling protocols, and official communication channels within Ethiopian government structure","Ability to maintain confidentiality of sensitive information and exercise discretion in handling official matters and interpersonal communications"]', '2024-01-14 21:00:00', '2024-02-14 21:00:00', '2025-12-17 19:48:37', '2025-12-17 19:48:37'),
(1, 'Public Health Officer', 'Lead community health initiatives and disease prevention programs. Conduct epidemiological surveillance and coordinate health education campaigns.', 'As a Public Health Officer for Lideta Subcity Government Office, you will play a critical role in protecting and improving community health through comprehensive public health initiatives, disease surveillance, and health education programs. Your responsibilities will encompass monitoring population health trends, investigating disease outbreaks, implementing preventive health measures, and coordinating with healthcare facilities and community organizations. You will develop and execute public health campaigns addressing prevalent health issues in the Lideta community, including infectious diseases, maternal and child health, nutrition, and non-communicable diseases. This position requires extensive fieldwork, data analysis, and community engagement to identify health disparities and implement targeted interventions. You will serve as a technical advisor on public health matters, providing evidence-based recommendations to government officials and collaborating with regional health authorities to align subcity initiatives with national health priorities and Sustainable Development Goals.', 'Lideta Health Center', '58000', 'fulltime', 'Health', '["epidemiology","community_engagement","data_analysis"]', '["Design, implement, and evaluate comprehensive public health programs addressing priority health issues in Lideta Subcity, including immunization campaigns, maternal health initiatives, disease prevention programs, and health promotion activities","Conduct regular community health assessments through household surveys, health facility data analysis, and epidemiological investigations to identify health trends, risk factors, and emerging public health threats","Investigate and respond to disease outbreaks and public health emergencies by conducting field investigations, coordinating response teams, implementing control measures, and monitoring containment efforts","Develop and deliver culturally appropriate health education materials, workshops, and community outreach programs targeting diverse populations including schools, religious institutions, workplaces, and community organizations","Monitor and evaluate health service delivery at public and private health facilities within the subcity, assessing quality of care, service availability, and compliance with national health standards and protocols","Collect, analyze, and report public health data using standardized reporting systems, preparing comprehensive epidemiological reports, situation analyses, and program evaluations for government officials and stakeholders","Coordinate with regional health bureaus, NGOs, community-based organizations, and healthcare providers to align public health efforts, leverage resources, and implement integrated health interventions","Provide technical guidance and capacity building to community health workers, health extension workers, and volunteers on public health practices, data collection methods, and health education techniques"]', '["Bachelor of Science degree in Public Health, Health Sciences, Nursing, or related field from an accredited university with coursework in epidemiology, biostatistics, and community health","Minimum of three years of practical public health experience in community health programming, disease surveillance, health education, or related fields within government or NGO settings","Comprehensive knowledge of Ethiopian public health system, national health policies, primary healthcare strategy, and priority health programs with understanding of local health challenges in urban settings","Demonstrated experience in epidemiological investigation, data collection and analysis, outbreak response, and use of health information systems for monitoring and evaluation purposes","Excellent community engagement and health communication skills with ability to develop culturally appropriate health messages and deliver effective health education to diverse populations","Strong analytical and problem-solving skills with ability to interpret health data, identify trends, and develop evidence-based recommendations for public health interventions","Proficiency in data analysis software (EPI Info, SPSS, or similar) and Microsoft Office applications for data management, analysis, and report preparation","Ability to work independently and collaboratively in multidisciplinary teams, manage multiple projects simultaneously, and adapt to changing public health priorities and emergencies"]', '2024-01-15 21:00:00', '2024-02-15 21:00:00', '2025-12-17 19:48:37', '2025-12-17 19:48:37'),
(1, 'Environmental Inspector', 'Enforce environmental regulations and conduct facility inspections. Monitor compliance with air quality and waste management standards.', 'As an Environmental Inspector for Lideta Subcity Government Office, you will be responsible for enforcing environmental regulations, conducting comprehensive inspections of commercial and industrial facilities, and ensuring compliance with national and municipal environmental standards. Your role involves systematic evaluation of pollution sources, waste management practices, and environmental impact of various activities within the subcity. You will conduct detailed inspections of manufacturing facilities, service establishments, construction sites, and residential developments to assess compliance with air quality standards, water pollution controls, waste disposal regulations, and noise pollution limits. This position requires technical knowledge of environmental science, regulatory frameworks, and inspection methodologies. You will investigate environmental complaints from residents, recommend corrective actions, and follow up on violations to ensure proper remediation. Additionally, you will contribute to environmental policy development and public education initiatives aimed at promoting sustainable practices within the Lideta community.', 'Lideta Subcity', '52000', 'fulltime', 'Environment', '["regulatory_compliance","environmental_monitoring","technical_reporting"]', '["Conduct scheduled and surprise inspections of industrial facilities, commercial establishments, construction sites, and service providers to assess compliance with environmental regulations, permits, and standards","Investigate environmental complaints from residents regarding pollution, improper waste disposal, noise violations, and other environmental concerns, documenting findings and recommending appropriate enforcement actions","Collect environmental samples (air, water, soil) following standardized protocols, coordinate laboratory analysis, interpret results, and prepare technical reports on environmental quality and pollution levels","Issue notices of violation, compliance orders, and administrative penalties to facilities failing to meet environmental standards, maintaining detailed records of enforcement actions and follow-up activities","Evaluate environmental impact assessments and management plans for proposed developments, providing technical recommendations and monitoring implementation of mitigation measures","Conduct environmental audits of facilities to assess overall environmental performance, identify improvement opportunities, and develop compliance schedules for corrective actions","Prepare comprehensive inspection reports with findings, observations, photographs, measurements, and recommendations for regulatory compliance and environmental protection","Provide technical guidance and education to business owners, facility managers, and community members on environmental regulations, pollution prevention techniques, and sustainable practices"]', '["Bachelor degree in Environmental Science, Environmental Engineering, Chemistry, or related field with specialized coursework in environmental regulations, pollution control, and environmental monitoring","Minimum of three years of professional experience in environmental inspection, compliance monitoring, pollution control, or regulatory enforcement within government or industrial settings","In-depth knowledge of Ethiopian environmental laws, regulations, standards, and permitting requirements at federal, regional, and municipal levels with understanding of enforcement procedures","Technical proficiency in environmental monitoring techniques, sampling protocols, field measurement equipment, and laboratory analysis methods for air, water, and soil quality parameters","Strong investigative and analytical skills with ability to interpret technical data, identify regulatory violations, and develop appropriate enforcement responses based on risk assessment","Excellent report writing and documentation skills with ability to prepare clear, comprehensive, and legally defensible inspection reports, violation notices, and compliance documentation","Effective communication and interpersonal skills with ability to explain complex environmental regulations to diverse audiences, negotiate compliance agreements, and handle confrontational situations professionally","Physical ability to conduct field inspections in various environments, including industrial facilities, construction sites, and potentially hazardous conditions, with appropriate safety precautions"]', '2024-01-16 21:00:00', '2024-02-16 21:00:00', '2025-12-17 19:48:37', '2025-12-17 19:48:37'),
(1, 'IT Support Technician', 'Provide technical support for government computer systems and networks. Troubleshoot hardware/software issues and maintain IT infrastructure.', 'As an IT Support Technician for Lideta Subcity Government Office, you will provide comprehensive technical support for all computer systems, networks, software applications, and peripheral devices used by government staff across multiple departments. Your responsibilities include installing, configuring, maintaining, and troubleshooting hardware and software systems to ensure optimal performance and minimal downtime. You will serve as the first point of contact for all IT-related issues, providing timely resolution to technical problems while maintaining detailed documentation of support requests and solutions. This position requires broad technical knowledge across multiple platforms and systems, with particular emphasis on government-specific applications and security protocols. You will also be responsible for managing user accounts, implementing security measures, conducting regular system maintenance, and providing basic training to staff on IT systems and applications. Additionally, you will assist in IT inventory management, procurement processes, and implementation of new technologies to improve government service delivery.', 'Lideta Subcity Office', '48000', 'fulltime', 'Technology', '["technical_troubleshooting","user_support","system_maintenance"]', '["Provide first-level technical support to government staff for hardware, software, network, and peripheral device issues through help desk ticketing system, phone support, and in-person assistance","Install, configure, and maintain desktop computers, laptops, printers, scanners, and other IT equipment according to government standards and security requirements","Troubleshoot and resolve technical issues with operating systems (Windows), productivity software (Microsoft Office), specialized government applications, and network connectivity problems","Manage user accounts, permissions, and access controls in Active Directory and other directory services, ensuring proper security protocols and compliance with government IT policies","Perform regular system maintenance including software updates, security patches, antivirus updates, and system backups to ensure optimal performance and data protection","Maintain detailed inventory records of IT equipment, software licenses, and consumables, tracking deployment, maintenance history, and retirement of assets according to government procedures","Provide basic training and guidance to government staff on proper use of IT systems, software applications, security practices, and troubleshooting techniques for common issues","Document technical procedures, solutions, and configurations in knowledge base system to improve support efficiency and ensure consistency in troubleshooting approaches"]', '["Diploma or Certificate in Information Technology, Computer Science, or related field with coursework in computer hardware, networking, and system administration","Minimum of two years of hands-on experience in IT support, help desk operations, or technical assistance role in organizational setting with diverse user base","Strong technical knowledge of Microsoft Windows operating systems, Microsoft Office Suite, desktop hardware components, printer configurations, and basic networking concepts","Experience with Active Directory user management, group policies, file permissions, and basic server administration in Windows Server environment","Proficiency in troubleshooting methodologies with ability to diagnose and resolve hardware, software, and network issues systematically and efficiently","Knowledge of cybersecurity principles, antivirus software, malware removal techniques, and data protection practices relevant to government IT environment","Excellent customer service and communication skills with ability to explain technical concepts to non-technical users patiently and clearly in both Amharic and English","Strong organizational skills with ability to prioritize multiple support requests, document solutions thoroughly, and follow established procedures for IT asset management"]', '2024-01-17 21:00:00', '2024-02-17 21:00:00', '2025-12-17 19:48:37', '2025-12-17 19:48:37'),
(1, 'Civil Engineer', 'Design and supervise municipal infrastructure projects. Ensure compliance with engineering standards and manage construction activities.', 'As a Civil Engineer for Lideta Subcity Government Office, you will be responsible for planning, designing, supervising, and managing municipal infrastructure projects that enhance community development and improve public services. Your role encompasses the entire project lifecycle from initial feasibility studies and conceptual design through construction supervision and final commissioning. You will work on diverse infrastructure projects including road improvements, drainage systems, water supply networks, public building construction, and urban development initiatives. This position requires strong technical expertise in civil engineering principles, project management capabilities, and knowledge of Ethiopian construction standards and regulations. You will coordinate with contractors, consultants, and government agencies to ensure projects are delivered on time, within budget, and to specified quality standards. Additionally, you will conduct site inspections, review technical submissions, prepare engineering drawings and specifications, and provide technical advice to government officials on infrastructure planning and development.', 'Lideta Engineering Office', '72000', 'fulltime', 'Infrastructure', '["project_management","structural_design","construction_supervision"]', '["Plan, design, and prepare detailed engineering drawings, specifications, and cost estimates for municipal infrastructure projects including roads, drainage systems, water supply networks, and public facilities using AutoCAD and engineering software","Supervise construction activities on-site to ensure compliance with engineering designs, specifications, quality standards, safety regulations, and environmental requirements","Conduct feasibility studies, site investigations, and technical assessments for proposed infrastructure projects, analyzing soil conditions, topographic features, and existing utilities","Review and approve contractor submissions including method statements, shop drawings, material samples, and quality control plans to ensure compliance with project requirements","Monitor project progress against schedules and budgets, preparing regular progress reports, identifying potential delays or cost overruns, and recommending corrective actions","Coordinate with utility companies, government agencies, contractors, and community stakeholders to facilitate project implementation, resolve conflicts, and minimize disruptions","Conduct quality control inspections and testing of construction materials, workmanship, and finished works according to Ethiopian standards and project specifications","Provide technical guidance and mentorship to junior engineers, engineering technicians, and site supervisors on engineering principles, construction methods, and project management practices"]', '["Bachelor of Science degree in Civil Engineering from accredited university with coursework in structural design, transportation engineering, water resources, and construction management","Professional engineering license from Ethiopian Ministry of Works and Urban Development or eligibility for licensure with demonstrated knowledge of Ethiopian engineering standards and codes","Minimum of four years of progressive civil engineering experience in infrastructure project design, construction supervision, or project management in government or consulting environment","Advanced proficiency in AutoCAD Civil 3D, engineering design software, and project management tools with ability to create detailed engineering drawings and technical specifications","Strong knowledge of Ethiopian construction standards, building codes, road design specifications, and environmental regulations applicable to municipal infrastructure projects","Proven project management skills with experience in planning, budgeting, scheduling, resource allocation, and risk management for engineering projects of varying scale and complexity","Excellent analytical and problem-solving abilities with capacity to evaluate engineering challenges, develop innovative solutions, and make sound technical decisions under pressure","Effective communication and coordination skills with ability to liaise with multiple stakeholders, write comprehensive technical reports, and present engineering concepts to diverse audiences"]', '2024-01-18 21:00:00', '2024-02-18 21:00:00', '2025-12-17 19:48:37', '2025-12-17 19:48:37'),
(1, 'Education Coordinator', 'Support school development and coordinate educational programs. Facilitate teacher professional development and monitor educational quality.', 'As an Education Coordinator for Lideta Subcity Government Office, you will play a pivotal role in enhancing educational quality, supporting school development, and implementing educational programs across public and private institutions within the subcity. Your responsibilities encompass monitoring educational standards, facilitating teacher professional development, coordinating educational initiatives, and serving as a liaison between schools and government education authorities. You will conduct regular school visits to assess teaching practices, learning environments, and administrative systems, providing constructive feedback and support for improvement. This position requires deep understanding of Ethiopian educational policies, curriculum frameworks, and pedagogical approaches, along with strong interpersonal skills to build collaborative relationships with school administrators, teachers, parents, and community organizations. You will also coordinate special education programs, extracurricular activities, and community engagement initiatives that complement formal education and address diverse learning needs within the Lideta community.', 'Lideta Education Office', '56000', 'fulltime', 'Education', '["educational_leadership","program_coordination","teacher_development"]', '["Conduct regular monitoring visits to public and private schools within Lideta Subcity to assess educational quality, teaching practices, learning outcomes, and compliance with national education standards","Coordinate and facilitate professional development programs, workshops, and training sessions for teachers, school administrators, and education professionals on curriculum implementation, pedagogy, and assessment practices","Implement and monitor government education initiatives, special programs, and pilot projects in schools, ensuring proper execution, documentation, and evaluation of program effectiveness","Serve as primary liaison between Lideta Subcity Education Office, individual schools, regional education bureau, and Ministry of Education, facilitating communication, policy implementation, and resource allocation","Organize and conduct regular meetings with school principals, parent-teacher associations, and community representatives to discuss educational challenges, share best practices, and develop improvement plans","Collect, analyze, and report educational data on enrollment, attendance, completion rates, examination results, and resource allocation to inform decision-making and policy development","Provide technical support and guidance to schools in developing school improvement plans, implementing inclusive education practices, and addressing specific learning needs of diverse student populations","Coordinate extracurricular activities, educational competitions, community service projects, and special events that enhance student learning, engagement, and holistic development"]', '["Bachelor degree in Education, Educational Leadership, Curriculum Development, or related field with specialization in pedagogy, educational administration, or teacher education","Minimum of four years of experience in educational coordination, school supervision, teacher support, or educational program management within government or school system","Comprehensive knowledge of Ethiopian education policy, curriculum framework, assessment system, teacher professional standards, and school accreditation requirements","Demonstrated experience in teacher professional development, instructional coaching, classroom observation, and feedback techniques that improve teaching practices and student learning","Strong analytical skills with ability to interpret educational data, identify trends and patterns, and develop evidence-based recommendations for educational improvement","Excellent interpersonal and communication skills with ability to build collaborative relationships with diverse stakeholders including teachers, administrators, parents, and government officials","Experience in organizing and facilitating workshops, training sessions, and professional learning communities for educators with focus on practical application and sustainable impact","Ability to manage multiple projects simultaneously, prioritize competing demands, and work effectively in team environment while meeting deadlines and achieving educational objectives"]', '2024-01-19 21:00:00', '2024-02-19 21:00:00', '2025-12-17 19:48:37', '2025-12-17 19:48:37'),
(1, 'Security Guard', 'Maintain safety and security at government office facilities. Conduct patrols and control access to protect government assets.', 'As a Security Guard for Lideta Subcity Government Office, you will be responsible for maintaining safety, security, and order at government facilities, protecting assets, personnel, and visitors from potential threats. Your role involves vigilant monitoring of premises, controlling access to restricted areas, conducting patrols, and responding to security incidents according to established protocols. You will serve as the first line of defense in protecting government property, confidential information, and public resources from theft, vandalism, unauthorized access, and other security risks. This position requires physical fitness, alertness, professional conduct, and knowledge of security procedures specific to government operations. You will interact daily with government employees, officials, and the public, requiring diplomacy and firmness in enforcing security policies. Additionally, you will maintain security logs, incident reports, and surveillance records, and collaborate with local law enforcement when necessary to address security concerns and maintain public trust in government facilities.', 'Lideta Subcity Office', '32000', 'fulltime', 'Security', '["access_control","surveillance_monitoring","incident_response"]', '["Control access to government facilities by verifying identification, screening visitors, issuing visitor badges, and monitoring entry/exit points according to established security protocols","Conduct regular patrols of buildings, grounds, parking areas, and perimeter fences to detect security vulnerabilities, unauthorized activities, safety hazards, or suspicious behavior","Monitor surveillance systems, alarm panels, and security equipment to identify potential security threats, respond to alarms, and maintain continuous security coverage of premises","Respond promptly to security incidents, emergencies, or disturbances by assessing situations, taking appropriate action according to procedures, and contacting supervisors or law enforcement as needed","Maintain detailed security logs, incident reports, visitor records, and daily activity reports documenting security observations, occurrences, and actions taken during shifts","Enforce government security policies and procedures regarding property removal, parking regulations, smoking restrictions, photography prohibitions, and other facility rules","Provide assistance and information to government employees, officials, and visitors regarding security procedures, facility directions, emergency protocols, and general inquiries","Perform security checks of offices, meeting rooms, and sensitive areas at opening and closing times, ensuring proper security of doors, windows, equipment, and confidential materials"]', '["Completion of secondary education with additional security training or certification from recognized security training institution or police academy","Minimum of two years of security experience in government facilities, corporate security, or public service environment with demonstrated reliability and professional conduct","Physical fitness and ability to stand for extended periods, walk patrol routes, respond quickly to incidents, and perform security duties in various weather conditions","Knowledge of basic security principles, access control procedures, surveillance systems, emergency response protocols, and incident reporting requirements","Alertness and observational skills with ability to detect unusual activities, identify potential security threats, and maintain vigilance during routine security duties","Good communication skills in Amharic with ability to interact professionally with diverse individuals, give clear instructions, and provide helpful assistance when needed","Ability to maintain confidentiality of sensitive information observed during security duties and exercise discretion in handling security matters","Clean criminal record and personal background with integrity, honesty, and professionalism suitable for government security position with public trust responsibilities"]', '2024-01-20 21:00:00', '2024-02-20 21:00:00', '2025-12-17 19:48:37', '2025-12-17 19:48:37'),
(1, 'Event Coordinator', 'Plan and organize government events and community meetings. Coordinate logistical arrangements for successful event execution.', 'As an Event Coordinator for Lideta Subcity Government Office, you will be responsible for planning, organizing, and executing a wide range of government events, community meetings, public consultations, and official ceremonies that facilitate citizen engagement and government communication. Your role encompasses every aspect of event management from initial concept development and logistical planning through on-site coordination and post-event evaluation. You will work with various government departments to identify event requirements, develop budgets, select venues, coordinate vendors, and manage all operational details to ensure successful outcomes. This position requires exceptional organizational skills, creativity, and ability to work under pressure while managing multiple events simultaneously. You will engage with diverse stakeholders including government officials, community leaders, service providers, and the public, requiring diplomacy, cultural sensitivity, and problem-solving abilities. Additionally, you will develop event protocols, evaluation mechanisms, and improvement strategies to enhance the quality and impact of government-sponsored events in serving Lideta community needs.', 'Lideta Community Center', '45000', 'fulltime', 'Event', '["logistical_planning","stakeholder_coordination","event_evaluation"]', '["Plan and coordinate all logistical aspects of government events including community meetings, public consultations, official ceremonies, training workshops, and cultural celebrations from conception to completion","Develop comprehensive event plans, timelines, budgets, and checklists for each event, identifying requirements, responsibilities, and contingency plans for potential challenges","Coordinate venue selection, setup arrangements, equipment rental, catering services, transportation, accommodations, and other vendor services according to event specifications and budget constraints","Prepare and distribute event communications including invitations, agendas, promotional materials, registration forms, and follow-up correspondence to participants, officials, and stakeholders","Manage on-site event operations including registration, audiovisual setup, speaker coordination, participant assistance, vendor supervision, and troubleshooting of issues as they arise","Develop and implement event evaluation mechanisms including participant surveys, feedback collection, and outcome assessment to measure event effectiveness and identify improvement opportunities","Coordinate with government departments, community organizations, media representatives, security personnel, and service providers to ensure seamless integration of all event elements","Maintain comprehensive event documentation including planning documents, financial records, participant lists, photographs, and evaluation reports for reference and reporting purposes"]', '["Diploma or degree in Event Management, Hospitality, Communications, Public Administration, or related field with coursework in event planning and project management","Minimum of three years of professional experience in event coordination, conference management, or public engagement activities in government, corporate, or nonprofit setting","Proven track record of successfully planning and executing diverse events of varying scale and complexity with demonstrated ability to manage budgets, timelines, and multiple stakeholders","Strong organizational and project management skills with ability to develop detailed event plans, coordinate multiple tasks simultaneously, and adapt quickly to changing circumstances","Excellent communication and interpersonal skills with ability to interact professionally with government officials, community leaders, vendors, and diverse participants in both Amharic and English","Creativity and problem-solving abilities with capacity to develop engaging event concepts, address logistical challenges innovatively, and ensure memorable participant experiences","Knowledge of local venue options, vendor networks, cultural protocols, and community dynamics in Addis Ababa with understanding of government event requirements and protocols","Proficiency in event management software, Microsoft Office applications, and basic graphic design tools for creating event materials, managing registrations, and preparing event documentation"]', '2024-01-21 21:00:00', '2024-02-21 21:00:00', '2025-12-17 19:48:37', '2025-12-17 19:48:37'),
(1, 'Revenue Collector', 'Collect municipal taxes and fees efficiently. Maintain accurate financial records and assist taxpayers with obligations.', 'As a Revenue Collector for Lideta Subcity Government Office, you will be responsible for the efficient collection of municipal taxes, fees, licenses, and other government revenues in accordance with established regulations and procedures. Your role involves direct interaction with taxpayers, businesses, and property owners to assess liabilities, process payments, issue receipts, and maintain accurate financial records. You will implement revenue collection strategies that maximize compliance while maintaining positive relationships with the community and ensuring transparency in government financial operations. This position requires strong numerical skills, integrity, and knowledge of municipal revenue systems, tax laws, and collection procedures. You will conduct field collections, follow up on arrears, maintain taxpayer records, and contribute to revenue forecasting and analysis. Additionally, you will provide information and assistance to taxpayers regarding their obligations, payment options, and available exemptions, while identifying potential revenue leakages and recommending improvements to collection processes and systems.', 'Lideta Revenue Office', '46000', 'fulltime', 'Administration', '["financial_management","tax_collection","record_keeping"]', '["Collect municipal taxes, fees, licenses, and other government revenues from individuals, businesses, and organizations according to established schedules, rates, and procedures","Issue official receipts, payment confirmations, and tax certificates for all collections, ensuring accurate documentation and proper accounting of all transactions","Maintain detailed records of revenue collections, taxpayer accounts, arrears, exemptions, and adjustments using manual registers and computerized revenue management systems","Conduct field collections and follow-up activities for delinquent accounts, communicating with taxpayers, explaining obligations, and arranging payment plans when appropriate","Verify taxpayer information, assess liabilities, calculate amounts due, and apply appropriate rates, exemptions, and penalties according to municipal regulations and policies","Prepare daily collection reports, reconciliation statements, and bank deposit slips, ensuring accuracy of financial records and timely transfer of collected funds to designated accounts","Provide information and assistance to taxpayers regarding tax obligations, payment procedures, available exemptions, appeal processes, and other revenue-related inquiries","Identify potential revenue leakages, non-compliance patterns, and collection challenges, recommending improvements to collection processes, systems, and taxpayer education initiatives"]', '["Diploma in Accounting, Finance, Business Administration, or related field with coursework in taxation, financial management, and record-keeping principles","Minimum of two years of experience in revenue collection, cash handling, financial transactions, or accounting functions in government, banking, or commercial environment","Strong numerical and computational skills with accuracy in calculating amounts, processing payments, and maintaining financial records according to accounting standards","Knowledge of municipal revenue systems, tax laws, fee structures, and collection procedures specific to Addis Ababa city administration and Lideta Subcity regulations","Integrity and honesty with ability to handle cash responsibly, maintain confidentiality of financial information, and demonstrate ethical conduct in revenue collection activities","Excellent communication and customer service skills with ability to explain tax requirements clearly, address taxpayer concerns professionally, and maintain positive community relations","Proficiency in basic computer applications including spreadsheet software, revenue management systems, and digital payment processing tools used in government collections","Attention to detail and organizational skills with ability to maintain accurate records, follow established procedures, and manage multiple taxpayer accounts simultaneously"]', '2024-01-22 21:00:00', '2024-02-22 21:00:00', '2025-12-17 19:48:37', '2025-12-17 19:48:37'),
(1, 'Sanitation Supervisor', 'Oversee waste collection and street cleaning services. Supervise sanitation workers and ensure service quality.', 'As a Sanitation Supervisor for Lideta Subcity Government Office, you will be responsible for overseeing waste collection, street cleaning, and sanitation services that maintain public health and environmental quality throughout the subcity. Your role involves direct supervision of sanitation workers, route planning, equipment maintenance, and quality assurance of cleaning operations. You will develop and implement efficient waste collection systems, monitor service delivery against established standards, and respond to community complaints regarding sanitation issues. This position requires practical knowledge of solid waste management principles, supervisory skills, and ability to coordinate operations across diverse urban neighborhoods. You will ensure compliance with municipal regulations, safety protocols, and environmental standards while optimizing resource utilization and service coverage. Additionally, you will conduct regular inspections of public areas, monitor contractor performance, maintain sanitation records, and develop improvement plans to address service gaps and enhance cleanliness standards in Lideta communities.', 'Lideta Sanitation Office', '50000', 'fulltime', 'Environment', '["waste_management","team_supervision","quality_inspection"]', '["Supervise daily sanitation operations including waste collection teams, street sweepers, and cleaning crews, ensuring proper performance of duties according to schedules and standards","Plan and optimize waste collection routes, service frequencies, and crew assignments to maximize efficiency, coverage, and responsiveness to community sanitation needs","Monitor equipment condition including collection vehicles, bins, hand tools, and personal protective equipment, scheduling maintenance, repairs, and replacements as needed","Conduct regular quality inspections of public areas, streets, markets, and communal spaces to assess cleanliness standards, identify problem areas, and direct corrective actions","Respond to and investigate sanitation complaints from residents, businesses, and community organizations, coordinating timely resolution and following up on service improvements","Maintain accurate records of sanitation operations including collection volumes, service coverage, equipment usage, personnel attendance, and incident reports for management review","Implement safety protocols and training programs for sanitation workers on proper lifting techniques, equipment operation, hazardous material handling, and personal protection measures","Coordinate with other municipal departments, private contractors, community organizations, and environmental agencies to address integrated waste management challenges and initiatives"]', '["Completion of secondary education with additional training in environmental management, waste management, public health, or supervisory skills from recognized institution","Minimum of three years of experience in sanitation operations, waste management, or environmental services with at least one year in supervisory or team leadership role","Practical knowledge of solid waste management principles, collection systems, equipment operation, and sanitation best practices in urban environment","Supervisory and leadership skills with ability to direct work teams, resolve conflicts, provide training, and maintain discipline among sanitation personnel","Familiarity with municipal sanitation regulations, environmental standards, safety requirements, and service quality expectations for public sanitation services","Physical ability to conduct field inspections, demonstrate work methods, and supervise operations in various weather conditions and urban environments","Problem-solving skills with capacity to analyze sanitation challenges, develop practical solutions, and implement improvements to service delivery systems","Valid driver license with ability to operate sanitation vehicles or supervise vehicle operations, and basic literacy in record-keeping and reporting requirements"]', '2024-01-23 21:00:00', '2024-02-23 21:00:00', '2025-12-17 19:48:37', '2025-12-17 19:48:37'),
(1, 'Social Worker', 'Provide social services to vulnerable individuals and families. Conduct assessments and coordinate support services.', 'As a Social Worker for Lideta Subcity Government Office, you will provide comprehensive social services to vulnerable individuals and families, addressing psychosocial needs, facilitating access to resources, and promoting social inclusion within the community. Your role involves assessment, counseling, case management, and advocacy for diverse client populations including children at risk, persons with disabilities, elderly individuals, economically disadvantaged families, and other marginalized groups. You will conduct home visits, develop care plans, coordinate with service providers, and implement interventions that enhance wellbeing and resilience. This position requires deep understanding of social work principles, Ethiopian social protection systems, and community resources, along with strong empathy, cultural competence, and ethical practice. You will maintain confidential case records, prepare reports, participate in multidisciplinary teams, and contribute to policy development addressing social issues. Additionally, you will organize support groups, community awareness activities, and capacity-building initiatives that strengthen social networks and promote protective environments for vulnerable populations in Lideta.', 'Lideta Social Office', '54000', 'fulltime', 'Health', '["counseling_skills","case_management","community_advocacy"]', '["Conduct comprehensive psychosocial assessments of individuals and families referred for social services, identifying needs, strengths, risks, and appropriate intervention strategies","Provide professional counseling services addressing emotional, behavioral, relationship, and adjustment issues using evidence-based therapeutic approaches tailored to client circumstances","Develop and implement individualized care plans with clients, setting achievable goals, identifying resources, coordinating services, and monitoring progress toward improved wellbeing","Conduct regular home visits and community outreach to engage with vulnerable populations, assess living conditions, provide in-situ support, and connect clients with essential services","Maintain detailed case records, progress notes, assessment reports, and service documentation according to professional standards and government reporting requirements","Coordinate with healthcare providers, educational institutions, legal services, employment programs, and community organizations to create integrated support networks for clients","Facilitate support groups, parenting workshops, life skills training, and community awareness sessions addressing prevalent social issues and building protective factors","Advocate for client rights and needs within government systems, service networks, and community settings, addressing barriers to access and promoting inclusive policies and practices"]', '["Bachelor of Social Work degree from accredited institution with coursework in counseling, case management, human behavior, and social welfare policy","Professional registration with relevant Ethiopian social work association or eligibility for registration with demonstrated knowledge of ethical standards and practice guidelines","Minimum of three years of professional social work experience in community-based setting with diverse client populations and complex psychosocial needs","Comprehensive knowledge of Ethiopian social protection system, community resources, referral pathways, and legal frameworks relevant to vulnerable populations","Strong counseling and interviewing skills with ability to establish rapport, conduct sensitive assessments, provide therapeutic support, and maintain professional boundaries","Case management expertise including assessment, planning, implementation, coordination, monitoring, and evaluation of services for individuals and families","Cultural competence and sensitivity in working with diverse populations, understanding community dynamics, traditional support systems, and appropriate intervention approaches","Excellent documentation and reporting skills with ability to maintain confidential records, prepare case summaries, and contribute to program evaluation and policy development"]', '2024-01-24 21:00:00', '2024-02-24 21:00:00', '2025-12-17 19:48:37', '2025-12-17 19:48:37'),
(1, 'Building Inspector', 'Examine construction projects for code compliance. Conduct inspections and provide technical guidance to contractors.', 'As a Building Inspector for Lideta Subcity Government Office, you will be responsible for examining construction projects at various stages to ensure compliance with building codes, zoning regulations, approved plans, and safety standards. Your role involves conducting detailed inspections of structural elements, electrical systems, plumbing installations, fire safety measures, and accessibility features in new construction, renovations, and existing buildings. You will review construction documents, issue inspection reports, identify code violations, and approve work progression based on compliance with regulatory requirements. This position requires technical knowledge of building systems, construction methods, and Ethiopian building codes, along with strong observational skills and attention to detail. You will interact with architects, engineers, contractors, property owners, and other stakeholders, providing technical guidance and enforcement of construction regulations. Additionally, you will investigate building complaints, dangerous structures, and illegal constructions, recommending corrective actions and follow-up measures to ensure public safety and regulatory compliance throughout Lideta Subcity.', 'Lideta Planning Office', '58000', 'fulltime', 'Infrastructure', '["code_enforcement","construction_inspection","technical_documentation"]', '["Conduct scheduled inspections at critical construction stages including foundation, framing, electrical, plumbing, mechanical, and final completion to verify compliance with approved plans and building codes","Review construction documents, architectural drawings, engineering calculations, and permit applications to understand project requirements and identify potential compliance issues","Issue inspection reports detailing findings, observations, measurements, photographs, and compliance status, specifying corrections needed for non-conforming work","Monitor and enforce compliance with building codes, zoning regulations, fire safety requirements, accessibility standards, and environmental provisions applicable to construction projects","Investigate complaints regarding illegal construction, building violations, unsafe conditions, or non-permitted work, documenting findings and recommending enforcement actions","Approve work progression by issuing inspection certificates, occupancy permits, and completion approvals when construction meets all regulatory requirements and standards","Provide technical guidance to contractors, architects, engineers, and property owners regarding code interpretation, compliance methods, and alternative solutions for unique situations","Maintain comprehensive inspection records, permit documentation, violation notices, and correspondence related to building regulation enforcement for legal and administrative purposes"]', '["Diploma or degree in Civil Engineering, Architecture, Building Technology, or related field with specialized knowledge of construction methods and building systems","Professional certification in building inspection, code enforcement, or construction supervision from recognized institution or government authority","Minimum of four years of experience in building construction, inspection, code enforcement, or related field with demonstrated knowledge of Ethiopian building codes and standards","Technical expertise in structural systems, electrical installations, plumbing configurations, mechanical equipment, fire protection, and accessibility requirements for buildings","Strong observational and analytical skills with ability to identify code violations, assess construction quality, detect safety hazards, and evaluate compliance with complex regulations","Knowledge of construction materials, testing procedures, installation methods, and industry best practices across various building types and construction techniques","Communication skills with ability to explain technical requirements clearly, document findings precisely, and interact professionally with diverse stakeholders in construction process","Physical ability to access construction sites, climb ladders, enter confined spaces, and conduct inspections in various weather conditions and construction environments"]', '2024-01-25 21:00:00', '2024-02-25 21:00:00', '2025-12-17 19:48:37', '2025-12-17 19:48:37'),
(1, 'Records Clerk', 'Organize and maintain government documents and archives. Implement records management systems and process requests.', 'As a Records Clerk for Lideta Subcity Government Office, you will be responsible for the systematic organization, maintenance, retrieval, and preservation of government documents, files, and archival materials essential for administrative operations and public service delivery. Your role involves implementing records management systems, classifying documents, creating finding aids, and ensuring proper storage conditions for both physical and digital records. You will process document requests, assist staff in locating information, and maintain confidentiality of sensitive materials according to government regulations. This position requires meticulous attention to detail, organizational skills, and knowledge of records management principles specific to government operations. You will contribute to digitization initiatives, disaster recovery planning, and records retention schedule implementation. Additionally, you will provide training to staff on proper records handling procedures, monitor compliance with documentation standards, and develop improvements to information management systems that enhance efficiency and accessibility of government records.', 'Lideta Archives Office', '38000', 'fulltime', 'Administration', '["document_classification","records_management","archival_preservation"]', '["Classify, index, and catalog government documents, files, and records according to established classification systems, metadata standards, and retrieval requirements","Maintain organized filing systems for physical documents including correspondence, reports, applications, permits, and official records with proper labeling and storage arrangements","Process document requests from government staff, officials, and authorized external parties by locating, retrieving, copying, and recording circulation of requested materials","Implement records retention schedules by identifying records eligible for destruction, transferring archival materials to permanent storage, and documenting disposal activities","Assist in digitization projects by preparing documents for scanning, verifying digital copies against originals, and entering metadata for electronic records management","Maintain proper storage conditions for archival materials including temperature and humidity control, pest prevention, and appropriate handling procedures for fragile documents","Create finding aids, indexes, catalogs, and databases to facilitate efficient retrieval of information from both physical and digital records collections","Provide training and guidance to government staff on proper records creation, classification, handling, and disposition procedures according to established policies and standards"]', '["Completion of secondary education with additional training in records management, archival science, library science, or information management from recognized institution","Minimum of two years of experience in records management, filing operations, archival work, or library services in organizational setting","Knowledge of records management principles, classification systems, retention schedules, and preservation techniques for both paper and electronic records","Attention to detail and organizational skills with ability to maintain systematic order in document collections, follow precise procedures, and ensure accuracy in records handling","Familiarity with government document types, filing requirements, confidentiality protocols, and administrative procedures specific to Ethiopian government operations","Basic computer skills including proficiency in word processing, spreadsheet applications, database entry, and scanning equipment operation for records management tasks","Ability to work independently with minimal supervision while maintaining productivity, accuracy, and adherence to established records management protocols","Physical ability to handle boxes of documents, operate filing equipment, and perform clerical tasks requiring manual dexterity and sustained attention to detailed work"]', '2024-01-26 21:00:00', '2024-02-26 21:00:00', '2025-12-17 19:48:37', '2025-12-17 19:48:37'),
(1, 'Public Relations Officer', 'Manage government communication with community. Develop public information campaigns and media relations.', 'As a Public Relations Officer for Lideta Subcity Government Office, you will be responsible for managing communication between government institutions and the community, developing public information strategies, and maintaining positive relationships with media outlets and stakeholders. Your role involves crafting clear, accurate, and timely communications about government policies, programs, services, and initiatives through various channels. You will prepare press releases, newsletters, social media content, and public announcements that enhance transparency, promote citizen engagement, and build public trust in government operations. This position requires strategic communication skills, media relations expertise, and understanding of public sector communication challenges and opportunities. You will monitor public opinion, analyze media coverage, respond to information requests, and develop communication plans for government initiatives. Additionally, you will organize press conferences, media briefings, and public forums, while training government staff on effective communication practices and managing crisis communication situations with professionalism and sensitivity to community concerns.', 'Lideta PR Office', '62000', 'fulltime', 'Administration', '["strategic_communication","media_relations","content_creation"]', '["Develop and implement comprehensive public relations strategies and communication plans that align with government priorities, enhance transparency, and promote citizen engagement","Prepare and distribute press releases, media advisories, official statements, newsletters, and other communication materials about government activities, programs, and achievements","Serve as primary media liaison by responding to journalist inquiries, arranging interviews, organizing press conferences, and maintaining positive relationships with media representatives","Monitor media coverage of government activities, analyze public sentiment, prepare media monitoring reports, and recommend communication adjustments based on feedback and trends","Manage government social media accounts, website content, and digital communication channels to disseminate information, engage with citizens, and address public inquiries","Organize and coordinate public information campaigns, community awareness programs, and outreach activities that explain government services, policies, and initiatives to diverse audiences","Develop communication materials for government officials including speeches, talking points, presentation slides, and briefing documents for public appearances and meetings","Provide media training and communication guidance to government staff and officials on effective messaging, interview techniques, public speaking, and crisis communication strategies"]', '["Bachelor degree in Communications, Public Relations, Journalism, Media Studies, or related field with coursework in strategic communication and media relations","Minimum of four years of professional experience in public relations, media relations, corporate communications, or journalism with portfolio of published work","Excellent writing and editing skills in both Amharic and English with ability to craft clear, accurate, and compelling communications for diverse audiences and platforms","Media relations expertise with established contacts in Ethiopian media landscape and demonstrated ability to manage relationships with journalists, editors, and media organizations","Strategic communication planning skills with ability to develop integrated campaigns, identify target audiences, select appropriate channels, and measure communication effectiveness","Digital communication proficiency including social media management, content creation, website updating, and understanding of online engagement strategies for public sector","Crisis communication experience with ability to develop response plans, manage sensitive situations, maintain calm under pressure, and protect organizational reputation","Knowledge of government communication protocols, public information policies, and ethical standards for official communications in Ethiopian public sector context"]', '2024-01-27 21:00:00', '2024-02-27 21:00:00', '2025-12-17 19:48:37', '2025-12-17 19:48:37'),
(1, 'Urban Planner', 'Develop urban planning initiatives for sustainable development. Analyze spatial data and review project compliance.', 'As an Urban Planner for Lideta Subcity Government Office, you will be responsible for developing, implementing, and monitoring urban planning initiatives that guide sustainable development, optimize land use, and enhance quality of life within the subcity. Your role involves analyzing spatial data, preparing development plans, reviewing projects for compliance, and engaging stakeholders in planning processes. You will work on comprehensive plans, zoning regulations, transportation networks, public space designs, and redevelopment projects that balance growth with environmental protection and community needs. This position requires technical expertise in urban planning principles, GIS applications, regulatory frameworks, and participatory planning methods. You will conduct site analyses, prepare maps and visualizations, evaluate development proposals, and provide recommendations to decision-makers. Additionally, you will facilitate public consultations, coordinate with other government agencies, conduct research on urban issues, and contribute to policy development addressing urbanization challenges and opportunities in Lideta Subcity.', 'Lideta Planning Office', '68000', 'fulltime', 'Infrastructure', '["spatial_analysis","planning_regulations","stakeholder_engagement"]', '["Develop comprehensive urban plans, land use maps, zoning regulations, and development guidelines that promote sustainable growth, efficient infrastructure, and improved quality of life","Review and evaluate development proposals, construction permits, and land subdivision applications for compliance with urban planning regulations, standards, and community objectives","Conduct spatial analysis using GIS software to assess land suitability, development patterns, infrastructure capacity, environmental constraints, and demographic trends","Prepare planning documents, technical reports, policy recommendations, and visual presentations that communicate planning concepts, analysis findings, and implementation strategies","Facilitate public participation processes including community meetings, stakeholder workshops, focus groups, and consultation events to gather input on planning initiatives","Coordinate with other government departments, utility providers, transportation agencies, and environmental authorities to ensure integrated planning and implementation of projects","Monitor urban development trends, land use changes, and implementation of planning policies, preparing periodic evaluation reports and recommending adjustments as needed","Provide technical advice to government officials, developers, community organizations, and other stakeholders on urban planning matters, regulatory requirements, and development opportunities"]', '["Bachelor or Master degree in Urban Planning, Urban Studies, Geography, Architecture, or related field with specialization in spatial planning and development management","Professional certification or registration as urban planner with relevant Ethiopian professional association or eligibility for certification","Minimum of four years of professional urban planning experience in government, consulting, or development sector with portfolio of completed planning projects","Advanced proficiency in GIS software (ArcGIS, QGIS), spatial analysis techniques, mapping tools, and data visualization methods for urban planning applications","Strong knowledge of Ethiopian urban planning legislation, land use regulations, building codes, environmental laws, and municipal planning frameworks","Analytical and research skills with ability to collect, interpret, and synthesize diverse data sources including demographic statistics, economic indicators, and spatial information","Communication and facilitation skills with ability to engage diverse stakeholders, present technical information clearly, and build consensus on planning decisions","Project management capabilities including planning, budgeting, timeline development, team coordination, and monitoring of planning initiatives from conception to implementation"]', '2024-01-28 21:00:00', '2024-02-28 21:00:00', '2025-12-17 19:48:37', '2025-12-17 19:48:37'),
(1, 'Health Educator', 'Develop health education programs for community health promotion. Design materials and conduct educational workshops.', 'As a Health Educator for Lideta Subcity Government Office, you will develop and implement comprehensive health education programs that promote healthy behaviors, prevent diseases, and improve health literacy within diverse community populations. Your role involves assessing community health needs, designing culturally appropriate educational materials, conducting workshops and training sessions, and evaluating program effectiveness. You will address priority health issues including infectious diseases, maternal and child health, nutrition, sanitation, non-communicable diseases, and mental health through evidence-based educational strategies. This position requires expertise in health communication, behavioral change theories, and participatory education methods adapted to various audience characteristics and learning styles. You will collaborate with healthcare providers, community organizations, schools, and media outlets to disseminate health messages and create supportive environments for healthy choices. Additionally, you will train community health workers, develop health promotion campaigns, conduct research on health behaviors, and contribute to policy development addressing health education needs in Lideta communities.', 'Lideta Health Center', '52000', 'fulltime', 'Health', '["health_communication","program_development","community_facilitation"]', '["Assess community health education needs through surveys, focus groups, interviews, and data analysis to identify priority topics, knowledge gaps, and behavioral risk factors","Develop culturally appropriate health education materials, visual aids, curriculum modules, and communication tools addressing identified health issues for diverse population groups","Design and implement health education programs, workshops, training sessions, and community events using participatory methods that engage learners and promote behavioral change","Conduct educational sessions in various community settings including schools, workplaces, religious institutions, community centers, and healthcare facilities","Evaluate health education interventions through pre/post assessments, participant feedback, behavioral monitoring, and outcome measurement to determine effectiveness and identify improvements","Train and support community health workers, volunteers, peer educators, and other stakeholders in health education techniques, message delivery, and facilitation skills","Develop and implement health promotion campaigns using multiple communication channels including print media, radio, social media, community radio, and interpersonal communication","Collaborate with healthcare providers, government agencies, NGOs, and community organizations to integrate health education into broader health initiatives and service delivery systems"]', '["Bachelor degree in Health Education, Public Health, Nursing, Health Sciences, or related field with coursework in health communication and behavioral change theories","Minimum of three years of professional experience in health education, health promotion, community health, or related field with demonstrated program development skills","Knowledge of Ethiopian health priorities, prevalent health issues, traditional health beliefs, and cultural factors influencing health behaviors in urban communities","Expertise in health communication strategies, educational methodologies, adult learning principles, and participatory techniques for diverse audience groups","Creative skills in developing health education materials, visual aids, interactive tools, and multimedia resources that effectively convey health messages and information","Facilitation and presentation skills with ability to engage audiences, adapt delivery to different learning styles, and create supportive learning environments","Evaluation and research skills with ability to assess educational needs, measure learning outcomes, analyze behavioral data, and report program effectiveness","Cultural competence and sensitivity in working with diverse communities, understanding social determinants of health, and adapting approaches to local contexts"]', '2024-01-29 21:00:00', '2024-02-27 21:00:00', '2025-12-17 19:48:37', '2025-12-17 19:48:37'),
(1, 'IT Systems Administrator', 'Design and maintain government network infrastructure. Ensure system reliability, performance, and security.', 'As an IT Systems Administrator for Lideta Subcity Government Office, you will be responsible for designing, implementing, maintaining, and securing the government network infrastructure, server systems, and IT services that support administrative operations and public service delivery. Your role encompasses system installation, configuration, monitoring, troubleshooting, and optimization to ensure reliability, performance, and security of critical IT assets. You will manage Windows Server environments, Active Directory services, email systems, backup solutions, and network equipment while implementing security measures to protect sensitive government data. This position requires advanced technical skills, problem-solving abilities, and knowledge of government IT requirements and security standards. You will develop system documentation, disaster recovery plans, and performance monitoring procedures, while providing technical leadership to IT support staff. Additionally, you will evaluate new technologies, plan system upgrades, coordinate with external service providers, and ensure compliance with government IT policies and cybersecurity regulations.', 'Lideta IT Office', '65000', 'fulltime', 'Technology', '["system_administration","network_security","infrastructure_management"]', '["Administer and maintain Windows Server environments including Active Directory, DNS, DHCP, Group Policy, file services, print services, and authentication systems","Design, implement, and secure government network infrastructure including routers, switches, firewalls, wireless access points, VPN connections, and internet connectivity","Monitor system performance, capacity, and security using management tools, analyzing trends, identifying issues, and implementing optimizations to maintain service levels","Implement and manage backup and disaster recovery solutions including regular backups, recovery testing, offsite storage, and business continuity planning","Configure and maintain email systems, collaboration platforms, antivirus solutions, patch management systems, and other enterprise applications used in government operations","Implement security measures including firewall rules, intrusion detection, access controls, encryption, security policies, and vulnerability management to protect government systems","Provide technical support escalation for complex IT issues, troubleshooting system failures, performance problems, and security incidents with systematic problem-solving approach","Develop and maintain system documentation, configuration records, network diagrams, operational procedures, and knowledge base articles for IT systems and infrastructure"]', '["Bachelor degree in Computer Science, Information Technology, Network Engineering, or related field with coursework in system administration and network security","Professional certifications in system administration (MCSA, MCSE) or networking (CCNA, Network+) with demonstrated technical expertise in enterprise IT environments","Minimum of four years of hands-on experience in system administration, network management, or IT infrastructure role in organizational setting","Advanced knowledge of Windows Server administration, Active Directory management, Group Policy implementation, and Microsoft enterprise services","Network administration skills including TCP/IP networking, routing protocols, VLAN configuration, firewall management, and wireless network implementation","Security expertise including security hardening, intrusion prevention, access control, encryption technologies, and compliance with government security standards","Problem-solving and troubleshooting abilities with systematic approach to diagnosing complex technical issues across multiple systems and network layers","Documentation and planning skills with ability to develop system documentation, operational procedures, disaster recovery plans, and technology roadmaps"]', '2024-01-31 21:00:00', '2024-02-29 21:00:00', '2025-12-17 19:48:37', '2025-12-17 19:48:37'),
(1, 'Traffic Officer', 'Manage traffic flow and enforce regulations. Investigate accidents and promote road safety.', 'As a Traffic Officer for Lideta Subcity Government Office, you will be responsible for managing traffic flow, enforcing traffic regulations, investigating accidents, and promoting road safety within the subcity jurisdiction. Your role involves directing traffic at congested intersections, monitoring compliance with traffic laws, issuing citations for violations, and responding to traffic incidents and emergencies. You will work to reduce traffic congestion, prevent accidents, and ensure orderly movement of vehicles and pedestrians through systematic enforcement and public education. This position requires knowledge of traffic regulations, enforcement procedures, accident investigation techniques, and public safety principles. You will interact daily with drivers, pedestrians, business owners, and community members, requiring diplomacy, firmness, and professionalism in potentially stressful situations. Additionally, you will collect traffic data, prepare incident reports, participate in safety campaigns, and collaborate with other law enforcement agencies to address traffic challenges and improve road safety outcomes in Lideta communities.', 'Lideta Traffic Office', '44000', 'fulltime', 'Security', '["traffic_control","enforcement_procedures","accident_investigation"]', '["Direct and control traffic flow at congested intersections, school zones, construction areas, and special events using hand signals, whistle commands, and traffic control devices","Enforce traffic regulations by monitoring vehicle operations, identifying violations, stopping offending vehicles, checking documentation, and issuing citations or warnings as appropriate","Investigate traffic accidents by securing scenes, documenting evidence, measuring skid marks, interviewing witnesses, preparing diagrams, and determining contributing factors","Respond to traffic emergencies, incidents, and obstructions by implementing temporary traffic controls, rerouting vehicles, coordinating with emergency services, and clearing hazards","Monitor parking regulations by patrolling designated areas, identifying violations, issuing parking citations, and arranging for vehicle removal when necessary","Collect traffic data through manual counts, speed measurements, congestion observations, and violation patterns to inform traffic management decisions and enforcement priorities","Provide public education on traffic safety through interactions with drivers and pedestrians, distribution of educational materials, and participation in community safety campaigns","Prepare detailed incident reports, violation records, daily activity logs, and statistical summaries documenting traffic enforcement activities, observations, and outcomes"]', '["Completion of secondary education with specialized traffic police training from recognized police academy or traffic enforcement training institution","Minimum of three years of experience in traffic management, law enforcement, or public safety role with demonstrated knowledge of traffic regulations and enforcement procedures","Physical fitness and stamina to stand for extended periods, direct traffic in various weather conditions, and perform traffic control duties in potentially hazardous environments","Knowledge of Ethiopian traffic laws, vehicle codes, enforcement procedures, accident investigation techniques, and traffic control methods","Observational and decision-making skills with ability to assess traffic situations quickly, identify violations accurately, and take appropriate enforcement actions","Communication and interpersonal skills with ability to interact professionally with diverse individuals, explain violations clearly, and maintain composure in confrontational situations","Basic report writing and documentation skills with ability to complete incident reports, violation forms, and activity logs accurately and legibly","Valid driver license with clean driving record and ability to operate traffic enforcement vehicles or motorcycles as required for patrol duties"]', '2024-02-01 21:00:00', '2024-03-01 21:00:00', '2025-12-17 19:48:37', '2025-12-17 19:48:37'),
(1, 'Part-time Cleaner', 'Maintain cleanliness of government office facilities. Perform cleaning tasks and ensure sanitary work environments.', 'As a Part-time Cleaner for Lideta Subcity Government Office, you will be responsible for maintaining cleanliness, hygiene, and orderly appearance of government office facilities through systematic cleaning procedures and attention to detail. Your role involves performing cleaning tasks in offices, meeting rooms, corridors, restrooms, and common areas according to established schedules and standards. You will ensure that work environments are sanitary, safe, and presentable for government staff, officials, and visitors, contributing to professional image and healthy working conditions. This position requires reliability, thoroughness, and understanding of proper cleaning techniques, equipment operation, and chemical safety. You will work independently with minimal supervision, managing time effectively to complete assigned tasks within designated hours while maintaining quality standards. Additionally, you will monitor cleaning supplies, report maintenance needs, follow safety protocols, and adapt cleaning routines to address specific needs or special events within government facilities.', 'Lideta Subcity Office', '18000', 'parttime', 'Environment', '["sanitary_cleaning","equipment_operation","attention_to_detail"]', '["Perform daily cleaning of assigned office areas including dusting furniture, wiping surfaces, emptying trash bins, vacuuming carpets, and mopping hard floor surfaces","Clean and sanitize restroom facilities including toilets, urinals, sinks, mirrors, fixtures, and floors, replenishing supplies such as toilet paper, soap, and paper towels","Clean windows, glass doors, and transparent partitions using appropriate cleaning solutions and techniques to maintain clear visibility and professional appearance","Clean kitchen and break room areas including countertops, appliances, sinks, and cabinets, ensuring hygienic conditions for food preparation and consumption","Perform periodic deep cleaning tasks including carpet shampooing, floor stripping and waxing, wall washing, and detailed cleaning of light fixtures and vents","Operate and maintain cleaning equipment including vacuum cleaners, floor buffers, carpet extractors, and other tools, performing basic maintenance and reporting malfunctions","Monitor and replenish cleaning supplies, notifying supervisor when inventory is low and assisting with stock organization and storage","Follow safety protocols for chemical handling, equipment operation, and personal protection, using appropriate protective gear and storing cleaning materials securely"]', '["Basic literacy and numeracy skills with ability to follow written and verbal instructions, complete simple forms, and understand cleaning schedules and procedures","Previous cleaning experience in office, commercial, or institutional setting with demonstrated knowledge of cleaning techniques, equipment operation, and chemical safety","Physical ability to perform cleaning tasks including standing, bending, lifting, pushing, and carrying cleaning equipment and supplies throughout work shift","Reliability and punctuality with consistent attendance, ability to work independently with minimal supervision, and commitment to completing assigned tasks thoroughly","Attention to detail with ability to identify areas needing cleaning, maintain consistent quality standards, and ensure comprehensive coverage of assigned areas","Basic understanding of cleaning chemical properties, dilution ratios, application methods, and safety precautions to ensure effective and safe cleaning practices","Ability to work flexible hours including early mornings, evenings, or weekends as required by cleaning schedules or special events at government facilities","Positive attitude and professional demeanor with respect for government property, consideration for office occupants, and discretion in handling confidential observations"]', '2024-02-03 21:00:00', '2024-02-19 21:00:00', '2025-12-17 19:48:37', '2025-12-28 17:46:04');
INSERT INTO `vacancy_translation` (`id`, `vacancy_id`, `amh`, `orm`, `created_at`) VALUES
(1, 1, '{"type":"ሙሉ ጊዜ","title":"አስተዳደራዊ ረዳት","salary":"42000","skills":["document_management","time_management","communication_skills"],"category":"አስተዳደር","location":"የልደታ ክፍለ ከተማ ቢሮ","description":"በልደታ ክፍለ ከተማ የመንግሥት ቢሮ እንደ አስተዳደራዊ ረዳት ለየክፍሉ መሪዎች አጠቃላይ የአስተዳደር ድጋፍ ማቅረብ እና በሁሉም ክፍሎች ላይ ለስላሳ የቀን በቀን አሠራር ማረጋገጥ የሚያስጠብቅዎት ነው። ሚናዎ ደብዳቤን ማስተዳደር፣ ስብሰባዎችን እና ቀጠሮዎችን ማስተባበር፣ የተደራጁ የፋይል ስርዓቶችን መጠበቅ እና ለውስጥ እና ውጫዊ ባለድርሻዎች ዋና የመገናኛ ነጥብ ሆነው ማገልገልን ያካትታል። ከከፍተኛ ባለሥልጣናት ጋር በቅርበት በመስራት ሪፖርቶችን፣ ማቅረቢያዎችን እና ኦፊሴላዊ ሰነዶችን ይዘጋጃሉ፤ በተመሳሳይ ጊዜ ከመንግሥት ፕሮቶኮሎች እና ሂደቶች ጋር ማጣጣልን ያረጋግጣሉ። ይህ ክፍል �ተለይቶ የተደራጁ ክህሎቶችን፣ ዝርዝር ትኩረትን እና በፍጥነት በሚተዳደር የመንግሥት አካባቢ ውስጥ ብዙ ቅድሚያዎችን የማስተዳደር ችሎታን ይጠይቃል። ከቢሮ አቅርቦት፣ ለስብሰባዎች እና ክንውኖች ሎጂስቲክስን ማስተባበር እና የሚመለከታቸውን የመንግሥት መረጃዎች ሚስጥርነትን መጠበቅንም ያስጠብቃሉ።","qualifications":["ቢያንስ ዲፕሎማ በቢሮ አስተዳደር፣ የንግድ አስተዳደር ወይም ተዛማጅ ዘርፍ ከተረጋገጠ ተቋም በአስተዳደር ሂደቶች እና በቢሮ ቴክኖሎጂ የተረጋገጠ የትምህርት ሥራ ጋር","ቢያንስ ሁለት ዓመት የሚበልጥ የሂደት አስተዳደራዊ ድጋፍ በመንግሥት ቢሮዎች፣ ኩባንያ አካባቢዎች ወይም ትላልቅ ድርጅቶች ሚስጥራዊ መረጃን በሚስጥርነት ለማስተዳደር የተረጋገጠ ችሎታ ጋር","የማይክሮሶፍት ኦፊስ ስፉት (Word, Excel, PowerPoint, Outlook) እና የመንግሥት ሰነድ አስተዳደር ስርዓቶች ላይ የላቀ ችሎታ፤ ውስብስብ ሰነዶችን፣ ሰንጠረዦችን እና ማቅረቢያዎችን የመፍጠር ችሎታ","በአማርኛ እና በእንግሊዝኛ ልዩ የተጻፈ እና የቃል የመገናኛ ክህሎቶች፤ ሙያዊ ደብዳቤ የመፃፍ ችሎታ እና በተለያዩ ባለድርሻዎች ጋር ውጤታማ ማገናኘት ችሎታ","ብዙ ስራዎችን በማስቀድም፣ በጊዜ መወጣት እና በከፍተኛ ግፊት ሁኔታዎች ውስጥ ዝርዝር ትኩረትን በመጠበቅ የተረጋገጠ የተደራጁ እና የጊዜ አስተዳደር ችሎታዎች","ከባለሥልጣናት፣ ከሰራተኞች እና ከማህበረሰብ አባላት ጋር አወንታዊ የሥራ ግንኙነት የመገንባት ችሎታ፤ በተመሳሳይ ጊዜ ሙያዊ ወሰን የመጠበቅ ችሎታ","በኢትዮጵያ የመንግሥት መዋቅር ውስጥ የመንግሥት አስተዳደር ሂደቶች፣ የሰነድ ማቀናበር ፕሮቶኮሎች እና ኦፊሴላዊ የመገናኛ መንገዶች እውቀት","ሚስጥራዊ መረጃን የመጠበቅ ችሎታ እና በኦፊሴላዊ ጉዳዮች እና በውስጥ ባለ የመገናኛ ሂደቶች ውስጥ የድርሻ አሰጣጥ የመጠቀም ችሎታ"],"responsibilities":["የየክፍሉ መሪዎችን የቀን መቁጠሪያ፣ ቀጠሮዎች እና ስብሰባዎች ያስተዳድሩ እና ያስተባብሩ፤ ምርጥ የጊዜ ሰሌዳ እና የጊዜ አስተዳደርን በማረጋገጥ ብዙ ቅድሚያዎች ላይ፤ ግጭቶችን በማስቀደም እና መፍትሄዎችን በማቅረብ","ኦፊሴላዊ ሰነዶችን፣ ሪፖርቶችን፣ ማቅረቢያዎችን እና ደብዳቤዎችን በመንግሥት ደረጃዎች እና ፕሮቶኮሎች መሠረት ያዘጋጁ፣ ይገምግሙ እና ያቀርፉ፤ ትክክለኛነት፣ አጠቃላይነት እና ሙያዊ ማቅረቢያን በማረጋገጥ","የአስተዳደር ሰነዶች፣ ደብዳቤዎች እና መዝገቦች ለሚሆኑ አጠቃላይ የኤሌክትሮኒክ እና አካላዊ የፋይል ማስቀመጫ ስርዓቶችን ያስቀምጡ፤ ውጤታማ የማሰባሰብ ስርዓቶችን በመተግበር እና ከመንግሥት የመዝገብ አስቀምጢ ደንቦች ጋር ማጣጣልን በማረጋገጥ","የየክፍሉ መሪዎች እና ሌሎች የመንግሥት ቢሮዎች፣ የማህበረሰብ ድርጅቶች እና ህዝብ መካከል ዋና መስመር ሆነው ያገለግሉ፤ ጥያቄዎችን በሙያዊ ሁኔታ በማስተናገድ እና ተገቢውን ሠራተኞች ያመላክታሉ","ለስብሰባዎች፣ ስብሰባዎች እና ኦፊሴላዊ ክንውኖች ሎጂስቲክስን ያስተባብሩ፤ ይህም የቦታ ማዘጋጀቶችን፣ የመሣሪያ ማዋቀርን፣ የምግብ አቅርቦትን እና የስብሰባ ቁሳቁሶችን እና አጀንዳዎችን ዝግጅት ያካትታል","የቢሮ አቅርቦት አክሲዮን፣ የግዥ ሂደቶች እና የመሣሪያ ጥገና ያስተዳድሩ፤ ፍላጎቶችን በማስቀደም እና የመሠረታዊ ሀብቶች ቀጣይነት ያለው የመገኘትን እንዲያረጋግጡ","ኦፊሴላዊ ደብዳቤዎችን፣ ማስታወሻዎችን እና የመገናኛዎችን ያክል እና ይከታተሉ፤ በጊዜ ማከፋፈልን እና ሁሉንም ኦፊሴላዊ የመገናኛዎች ተገቢ ሰነድ አድርጎ ማቅረብን ያረጋግጡ","በገንዘብ መዝገቦችን በመከታተል፣ ፋክተሮችን በማከናወን እና ለየክፍሉ አሠራር የገንዘብ መዝገቦችን በመጠበቅ በጀት አዘጋጅታ እና ቁጥጥር ላይ ይረዱ"],"short_description":"የቀን በቀን የቢሮ አሠራርን አስተባብር እና ለየክፍሉ መሪዎች አጠቃላይ የአስተዳደር ድጋፍ ያቅርቡ። ደብዳቤ እና የጊዜ ሰሌዳ ያስተዳድሩ።"}', '{"type":"Yeroo Guutuu","title":"Gargaarsa Bulchinsaa","salary":"42000","skills":["document_management","time_management","communication_skills"],"category":"Bulchinsa","location":"Mana Hojii Lideta Sub-City","description":"Mana hojii mootummaa Lideta Sub-City keessatti akka Gargaarsa Bulchinsaa taateen, gargaarsa bulchinsaa guutuu hoggantoota qoqqoodaaf kennuufi hojii guyyataan walqabataa hunda qoqqooda keessatti mirkaneessuuf dhaabbata. Rooliin kee gaaffiiwwan bulchuu, walgahiiwwanfi beellamawwan walitti fiduu, sirna galmee qoqqoodamee turuufi tajaajiltoota dhuunfaa fi alaa gidduu bu\'aa addaa taatee tajaajiluudha. Dhaabbileen ol aanaa wajjin walitti shira gahee, gabaa, fudhannoo fi dhaabbilee mootummaa qopheessuudhaan hojjettu; yeroo hundaa waliigala mootummaa fi tarsiimoota wajjin mirkaneessuudhaan. Kanaaf mijata qindoomina addaa, ibsa xiqqoo, fi dandeettii mijataa muraasa adda addaa loltuu bulchii mootummaa ariifaa ta\'e keessatti bulchuun barbaachisa. Dabalataan, oomisha mana hojii, lojistikii walgahiifi taatee, fi icciti mootummaa icciti ta\'e turuuf dhaabbata.","qualifications":["Diploomaa bu\'aa ta\'e Hojii Bulchinsaa, Hojii Daldalaa, ykn qoqqooda walitti dhufeenya mana hojii, fi dandeettii tarsiimoo bulchinsaa fi teknooloojii mana hojii irratti argame","Waggaa lama yoo ta\'u ol hojii gargaarsa bulchinsaa deemaa ta\'e mana hojii mootummaa, naannoo shirkii, ykn dhaabbilee guddaa keessatti, fi dandeettii mirkaneessaa icciti icciti ta\'e bulchuuf","Dandeettii ol aanaa Suutii Makiirsoosoofiti Ofiisii (Word, Excel, PowerPoint, Outlook) fi sirna bulchuu dhaabbilee mootummaa, fi dandeettii dhaabbilee sirnaa, liqimssaa, fi fudhannoo uumuuf","Dandeettii barreeffamaafi dubbii ol aanaa Afaan Oromoo fi Ingiliffaa keessatti, fi dandeettii mirkaneessaa gaaffii hojii qopheessuufi tajaajiltoota adda addaa wajjin bilbilaa bu\'aa qabu taasisuuf","Dandeettii qindoominaafi yeroo bulchii mirkaneessaa, fi dandeettii hojii muraasa qajeelchuuf, beellama guutuu, fi ibsa xiqqoo naannoo cimaa ta\'e keessatti turuuf","Dandeettii walitti dhufeenya namaa cimaa, fi dandeettii dhaabbileen, hojjattoota, fi miseensa hawaasaa wajjin qajeelfama hojii ol\'aanaa uumuuf, yeroo hundaa daangeffama hojii turuudhaan","Beekumsa tarsiimoo bulchinsaa mootummaa, waliigala dhaabbilee bulchuuf, fi karaa bilbilaa mootummaa qaama mootummaa Itoophiyaa keessatti","Dandeettii icciti icciti ta\'e turuuf, fi dandeettii dhimma mootummaa fi tarsiimoo bilbilaa namaa gidduu keessatti murannoo fayyadamuuf"],"responsibilities":["Hoggantoota qoqqoodaaf kalaandarii, beellamawwan, fi walgahiiwwan bulchiifi walitti fidi, sa\'ataa fi yeroon bulchii mijataa adda addaa walitti fidi, walgahiiwwan dhabamsiisuu fi furmaata dhiyeessuu","Dhaabbilee mootummaa, gabaa, fudhannoo, fi gaaffiiwwan sirnaafi waliigala mootummaa irratti hundaa\'e qopheessi, xiinxali, fi suuta, dhugaa, waliigala, fi fudhannoo hojii dhaabbachuu mirkaneessi","Sirna galmee elektirootikii fi qaamaa dhaabbilee bulchinsaa, gaaffiiwwan, fi galmeewwanif qopheessi, sirna deebi\'ii bu\'aa qabu taasisi, fi waliigala galmee mootummaa wajjin mirkaneessi","Hoggantoota qoqqooda fi mana hojii mootummaa biroo, dhaabbilee hawaasaa, fi ummata gidduu bu\'aa addaa ta\'i, gaaffiiwwan akka hojii tiin deebisi, fi hojjattoota sirrii ta\'an gorsisi","Lojistikii walgahii, hirmaannaa, fi taatee mootummaaaf walitti fidi, kan isaaniis qophii bakka, qophii meeshaa, kennumsa nyaataa, fi qophii meeshaa walgahii fi ajandaa","Akkawuntii oomisha mana hojii, tarsiimoo bitaa, fi eegumsa meeshaa bulchi, fedhiiwwan dhabamsiisuu, fi argina dhaabbataa qabeenya bu\'aa ta\'e mirkaneessuu","Gaaffiiwwan, yaad-rifeensa, fi bilbilaa mootummaa haalaafi galmeessi, yeroo hundaa qoqqooduu, fi dhaabbileen bilbilaa mootummaa hundaa galmee sirrii ta\'e dhaabbachuu mirkaneessi","Bajetii qopheessuufi ilaaluu keessatti gargaari, baasiiwwan ilaaluu, faayilota qorichaa haalaafi, fi galmee maallaqa hojii qoqqoodaaf turu"],"short_description":"Hojii mana hojii guyyataan walitti fidi, gargaarsa bulchinsaa guutuu hoggantoota qoqqoodaaf kenni. Gaaffiiwwanfi sa\'ataa bulchi."}', '2025-12-20 12:19:20'),
(1, 1, '{"type":"ሙሉ ጊዜ","title":"ጤና ባለሙያ","salary":"58000","skills":["epidemiology","community_engagement","data_analysis"],"category":"ጤና","location":"የልደታ ጤና ማዕከል","description":"ለልደታ ክፍለ ከተማ የመንግሥት ቢሮ እንደ ጤና ባለሙያ፣ አጠቃላይ የህዝብ ጤና ተቋሞች፣ የበሽታ ክትትል እና የጤና ትምህርት ፕሮግራሞች በኩል የማህበረሰብ ጤናን ለመጠበቅ እና ለማሻሻል ወሳኝ ሚና ትጫወታላችሁ። ኃላፊነቶቻችሁ የህዝብ ቁጥር የጤና አዝማሚያዎችን መከታተል፣ የበሽታ ስርጭቶችን መርምር፣ የመከላከያ የጤና እርምጃዎችን መተግበር እና ከጤና አገልግሎት ተቋማት እና የማህበረሰብ ድርጅቶች ጋር ማስተባበርን ያካትታሉ። በልደታ ማህበረሰብ ውስጥ ተራ የሆኑ የጤና ጉዳዮችን የሚያስተናግዱ የህዝብ ጤና ዘመቻዎችን ይዘጋጃሉ እና ያከናውናሉ፣ እነዚህም ከተላላፊ በሽታዎች፣ ከእናት እና የህጻናት ጤና፣ ከአመጋገብ እና ከተላላፊ ያልሆኑ በሽታዎች ጋር የተያያዙ ናቸው። ይህ ክፍል በልደታ ማህበረሰቦች ውስጥ የጤና እኩልነትን ለመለየት እና ተለይተው የተዘጋጁ እርምጃዎችን ለማስገባት በሜዳ ሥራ፣ በውሂብ ትንተና እና በማህበረሰብ ተሳትፎ የሚፈለግ ነው። በህዝብ ጤና ጉዳዮች ላይ የቴክኒክ አማካሪ በመሆን የሚያገለግሉ ሲሆን ለመንግሥት ባለሥልጣናት በማስረጃ ላይ የተመሰረቱ ምክሮችን ያቀርባሉ እና ከክልላዊ ጤና ባለስልጣናት ጋር በመስራት የክፍለ ከተማ ተቋሞችን ከብሔራዊ የጤና ቅድሚያዎች እና ከተጣራ የልማት ግቦች ጋር ያስባረራሉ።","qualifications":["የሳይንስ ባችለር ዲግሪ በህዝብ ጤና፣ በጤና ሳይንስ፣ በነርሲንግ ወይም ተዛማጅ ዘርፍ ከተረጋገጠ ዩኒቨርሲቲ በሕማም ምልክት፣ በባዮስታቲስቲክስ እና በማህበረሰብ ጤና የተረጋገጠ የትምህርት ሥራ ጋር","ቢያንስ ሶስት ዓመት በማህበረሰብ ጤና ፕሮግራም፣ በበሽታ ክትትል፣ በጤና ትምህርት ወይም በመንግሥት ወይም በኤንጂኦ ሁኔታዎች ውስጥ በተዛማጅ መስኮች ውስጥ ተግባራዊ የህዝብ ጤና ልምድ","የኢትዮጵያ ህዝብ ጤና ስርዓት፣ ብሔራዊ የጤና ፖሊሲዎች፣ የመጀመሪያ ደረጃ የጤና ማንከባከብ ስትራቴጂ እና ቅድሚያ የጤና ፕሮግራሞች አጠቃላይ እውቀት፤ በከተማ ሁኔታዎች ውስጥ አካባቢያዊ የጤና ተግዶላዎችን መረዳት","በሕማም ምልክት ምርመራ፣ በውሂብ ስብሰባ እና ትንተና፣ በስርጭት ምላሽ እና በጤና መረጃ ስርዓቶች አጠቃቀም ለክትትል እና ለግምገማ ዓላማዎች የተረጋገጠ ልምድ","በማህበረሰብ ተሳትፎ እና በጤና መገናኛ ላይ አስተማማኝ ክህሎቶች፤ ከባህል ግንኙነት ያላቸው የጤና መልዕክቶችን የመፍጠር ችሎታ እና ለተለያዩ ህዝቦች ውጤታማ የጤና ትምህርት ማቅረብ ችሎታ","በጤና ውሂብ ትርጉም መስጠት፣ አዝማሚያዎችን መለየት እና ለህዝብ ጤና እርምጃዎች በማስረጃ ላይ የተመሰረቱ ምክሮችን የመገንባት ችሎታ ጋር ጠንካራ የትንተና እና የችግር መፍታት ክህሎቶች","በውሂብ ትንተና ሶፍትዌር (EPI Info, SPSS, ወይም ተመሳሳይ) እና በማይክሮሶፍት ኦፊስ መተግበሪያዎች ላይ በውሂብ አስተዳደር፣ በትንተና እና በሪፖርት አዘጋጅታ ላይ ችሎታ","በብዙ የሙያ ቡድኖች ውስጥ በነጻ እና በአንድነት መስራት ችሎታ፣ ብዙ ፕሮጀክቶችን በአንድ ጊዜ ማስተዳደር ችሎታ እና ለሚቀያየሩ የህዝብ ጤና ቅድሚያዎች እና አደጋዎች የመስማማት ችሎታ"],"responsibilities":["በልደታ ክፍለ ከተማ ውስጥ ቅድሚያ ያላቸውን የጤና ጉዳዮች የሚያስተናግዱ አጠቃላይ የህዝብ ጤና ፕሮግራሞችን ይንደፉ፣ ያተግብሩ እና ይገምግሙ፤ እነዚህም የመከላከያ ዘመቻዎችን፣ የእናት ጤና ተቋሞችን፣ የበሽታ መከላከያ ፕሮግራሞችን እና የጤና ማሻሻያ እንቅስቃሴዎችን ያካትታሉ","በቤት ምርመራዎች፣ በጤና ተቋም ውሂብ ትንተና እና በሕማም ምልክት ምርመራዎች በኩል መደበኛ የማህበረሰብ ጤና ግምገማዎችን ያካሂዱ፤ የጤና አዝማሚያዎችን፣ የአደጋ ነገሮችን እና እየተዳደጉ ያሉ የህዝብ ጤና አደጋዎችን ለመለየት","የበሽታ ስርጭቶችን እና የህዝብ ጤና አደጋዎችን በመርምር እና በመቀበል፤ በሜዳ ምርመራዎችን በመካሄድ፣ የምላሽ ቡድኖችን በማስተባበር፣ የቁጥጥር እርምጃዎችን በመተግበር እና በመያዝ ላይ ያሉ ጥረቶችን በመከታተል","የባህል ግንኙነት ያላቸውን የጤና ትምህርት ቁሳቁሶችን፣ አውደ ማሰልጠኛዎችን እና የማህበረሰብ ማድረሻ ፕሮግራሞችን ይዘጋጁ እና ያቅርቡ፤ ይህም ትምህርት ቤቶችን፣ ሃይማኖታዊ ተቋማትን፣ የሥራ ቦታዎችን እና የማህበረሰብ ድርጅቶችን ያገባል","በክፍለ ከተማው ውስጥ በህዝብ እና በግል ጤና ተቋማት ላይ የጤና አገልግሎት አቅርቦትን ይከታተሉ እና ይገምግሙ፤ የእርካታ ጥራትን፣ የአገልግሎት ተገኝነትን እና ከብሔራዊ የጤና ደረጃዎች እና ፕሮቶኮሎች ጋር ማጣጣልን በመገምገም","የህዝብ ጤና ውሂብን በመደበኛ የሪፖርት ስርዓቶች በመጠቀም ይሰብስቡ፣ ይተነትኑ እና ይለጥፉ፤ ለመንግሥት ባለሥልጣናት እና ባለድርሻዎች አጠቃላይ የሕማም ምልክት ሪፖርቶችን፣ የሁኔታ ትንተናዎችን እና የፕሮግራም ግምገማዎችን ያዘጋጁ","ከክልላዊ ጤና ቢሮዎች፣ ከኤንጂኦዎች፣ ከማህበረሰብ የተመሰረቱ ድርጅቶች እና ከጤና አገልግሎት አቅራቢዎች ጋር ያስተባብሩ፤ የህዝብ ጤና ጥረቶችን ለማስተካከል፣ ሀብቶችን ለማጎልበት እና የተቀናጀ የጤና እርምጃዎችን ለማስገባት","በህዝብ ጤና ልምምዶች፣ በውሂብ ስብሰባ ዘዴዎች እና በጤና ትምህርት ቴክኒኮች ላይ ለማህበረሰብ ጤና ሠራተኞች፣ ለጤና ማስፋፊያ ሠራተኞች እና ለበጎ ፈቃደኞች ቴክኒካዊ መመሪያ እና አቅም ግንባታ ያቅርቡ"],"short_description":"የማህበረሰብ ጤና ተቋሞችን እና የበሽታ መከላከያ ፕሮግራሞችን ያስተዳድሩ። የሕማም ምልክት ክትትል ያካሂዱ እና የጤና ትምህርት ዘመቻዎችን ያስተባብሩ።"}', '{"type":"Yeroo Guutuu","title":"Hojjeta Fayyaa Ummataa","salary":"58000","skills":["epidemiology","community_engagement","data_analysis"],"category":"Fayyaa","location":"Giddugaleessa Fayyaa Lideta","description":"Lideta Sub-City mana hojii mootummaa keessatti akka Hojjeta Fayyaa Ummataa taateen, fayyaa hawaasaa eeguufi fooyya\'isuuf, surveillance dhukkubaa, fi pirograamoonni barsiisa fayyaa wajjin dhimma murteessaa taphatta. Dhimmiwwan kee dhangaa\'aa fayyaa ummataa ilaaluu, dhukkuba baasuun qoruu, tarkaanfii fayyaa dhorguu raawwachiisuufi, mana fayyaafi dhaabbilee hawaasaa wajjin walitti shira godhuu dha. Pirograamoonni fayyaa ummataa fi kampaaniiwwan kanneen dhukkuboota mul\'atan Lideta hawaasa keessatti, kanneen dhukkuboota dhiigaa, fayyaa haadhaafi daa\'immaa, nyaataafi dhukkuboota dhiigaa hin qabne kanneen dabalatan qopheessuufi raawwatudha. Kun tajaajila naannoo, qorannoo daataa, fi hawaasa haala keessatti hirmaachuufi fedhiin fayyaa walsimsiisuufi tarkaanfilee kanneen dhukkuboota adda addaa itti fufuuf dha. Akka ammayyaatti, dhimma fayyaa ummataa irratti gorsa teknikaalaa kennita, dhaabbileen mootummaaaf yaada mirkaneessaa kennita, fi waliigala fayyaa naannoo wajjin walitti shira godhaa kaayyoo sub-city qoqqooda waliigala fayyaa fi kaayyoo guddisa dhaabbataa wajjin walitti hidhuu dha.","qualifications":["Digirii Saayinsii Baachilerii fayyaa ummataa, Saayinsii Fayyaa, Naarsii, ykn qoqqooda walitti dhufeenya irraa kan ta\'e yunivarsiitii amanamaa ta\'e, kanneen epidemiology, biostatistics, fi fayyaa hawaasaa wajjin qophaa\'e","Waggaa sadi yoo ta\'u ol tajaajila fayyaa ummataa naannoo, pirograamii fayyaa hawaasaa, surveillance dhukkuba, barsiisa fayyaa, ykn qoqqooda walitti dhufeenya mootummaa ykn NGO keessatti","Beekumsa guutuu sirna fayyaa ummataa Itoophiyaa, sirna fayyaa waliigalaa, strateejii tajaajila fayyaa jalqabaa, fi pirograamoonni fayyaa murteessaa fi beekumsa dhibee fayyaa naannoo naannoo magaalaa keessatti","Beekumsa mirkaneessaa qorannoo epidemiolojikii, qabsiifannaa daataafi qorannoo, deebii ba\'aa, fi fayyadama sirna iccitii fayyaa eeguufi qorannoo","Dandeettii gammachiisaa hawaasaa fi bilbilaa fayyaa ol\'aanaa, fi dandeettii oggaa fayyaa aadaa uumuufi barsiisa fayyaa bu\'aa qabu haala adda addaa irratti kennuuf","Dandeettii qorannoofi furmaata dhibee cimaa, fi dandeettii daataa fayyaa hiikuu, dhangaa\'aa ilaaluu, fi yaada mirkaneessaa tarkaanfii fayyaa ummataaf qopheessuuf","Dandeettii ol\'aanaa sooftiweerii qorannoo daataa (EPI Info, SPSS, ykn fakkaataa) fi Microsoft Office fayyadamuuf qabsiifannaa daataa, qorannoo, fi qophii gabaa","Dandeettii hojii dhuunfaa fi walitti shira garee adda addaa keessatti, piroojektii muraasa yeroo tokko bulchuufi, fi dandeettii jijjiirama murteessaa fayyaa ummataa fi yeroo barbaachisaa wajjin walqabataa ta\'uuf"],"responsibilities":["Pirograamoonni fayyaa ummataa guutuu kanneen dhimma fayyaa murteessaa Lideta Sub-City keessatti, kanneen kampaanii tarkaanfii, kaayyoo fayyaa haadhaa, pirograamoonni dhukkuba dhorguu, fi gochaalee fayyaa daddabsiisuu dabalatan qopheessi, raawwachiisi, fi qorannoo","Madaala fayyaa hawaasaa yeroo yeroo ta\'e kanneen gaaffii manaa, qorannoo daataa mana fayyaa, fi qorannoo epidemiolojikii wajjin raawwachiisi akka dhangaa\'aa fayyaa, dhibee, fi dhukkuba fayyaa ummataa itti aanu mul\'atu ilaaluuf","Dhukkuba baasuun fi deebii dhukkuba fayyaa ummataa yeroo barbaachisaa ta\'e ilaaluufi deebisuu, kanneen qorannoo naannoo, garee deebii walitti fiduu, tarkaanfii tajaajiluufi, fi tajaajila dhukkuba itti fufuuf eeguu wajjin raawwachiisi","Meeshaa barsiisa fayyaa kanneen aadaa, waaksiiwwan, fi pirograamoonni hawaasaa deemu kanneen barumsa, dhaabbilee amantaa, bakka hojii, fi dhaabbilee hawaasaa kanneen hordofu qopheessiifi kenni","Tajaajila fayyaa mana fayyaa ummataafi kan dhuunfaa sub-city keessatti eeguufi qorannoo, sirna fayyaa waliigalummaa, argina tajaajilaa, fi waliigala waliigala fayyaa fi waliigala waliigalaa wajjin walqabataa ilaaluu","Daataa fayyaa ummataa sirna galmaa\'aa fayyadamuun qabsiifi, qorannoo, fi galmee, gabaa guutuu epidemiolojikii, qorannoo haala, fi qorannoo pirograamii dhaabbileen mootummaa fi tajaajiltootaaf qopheessi","Waliigala fayyaa naannoo, NGO, dhaabbilee hawaasa irraa kanneen, fi kennaawwan fayyaa wajjin walitti shira godhaa kaayyoo fayyaa ummataa, qabeenya fayyadamuufi, fi tarkaanfii fayyaa waliigalaa raawwachiisuuf","Gorsa teknikaalaa fi qabeenya ijaarsaa hojjattoota fayyaa hawaasaa, daddabartoota fayyaa, fi fedhiiftoota dhimma tajaajila fayyaa ummataa, daataa qabsiifachuu, fi mala barsiisa fayyaa irratti kenni"],"short_description":"Kaayyoo fayyaa hawaasaa fi pirograamoonni dhukkuba dhorguu qajeelchi. Surveillance epidemiologikii gaggeessi, kampaanii barsiisa fayyaa walitti fidi."}', '2025-12-20 12:38:42'),
(1, 1, '{"type":"ሙሉ ጊዜ","title":"የአካባቢ ተቆጣጣሪ","salary":"52000","skills":["regulatory_compliance","environmental_monitoring","technical_reporting"],"category":"አካባቢ","location":"ልደታ ክፍለ ከተማ","description":"ለልደታ ክፍለ ከተማ የመንግሥት ቢሮ እንደ የአካባቢ ተቆጣጣሪ፣ የአካባቢ ደንቦችን ማስከበር፣ የንግድ እና የኢንዱስትሪ ተቋማትን አጠቃላይ ክትትሎችን ማካሄድ እና ከብሔራዊ እና ከከተማ የአካባቢ ደረጃዎች ጋር ማጣጣልን ማረጋገጥ የሚያስጠብቅዎት ነው። ሚናዎ የመርከቦች ምንጮች፣ የነፍሳት አስተዳደር ልምዶች እና የአካባቢ ተጽዕኖ የተለያዩ እንቅስቃሴዎችን በክፍለ ከተማው ውስጥ የሚረጋገጥ ስርዓታዊ ግምገማን ያካትታል። የአየር ጥራት ደረጃዎች፣ የውሃ ብክለት ቁጥጥሮች፣ የነፍሳት ማስወገጃ ደንቦች እና የድምፅ ብክለት ገደቦችን ለመገምገም የማምረቻ ተቋማትን፣ የአገልግሎት መስሪያ ቤቶችን፣ የግንባታ ቦታዎችን እና የመኖሪያ ልማቶችን ዝርዝር ክትትሎችን ያካሂዳሉ። ይህ ክፍል የአካባቢ ሳይንስ፣ የአስተዳደር መዋቅሮች እና የክትትል ዘዴዎች ቴክኒካዊ እውቀትን ይጠይቃል። የነዋሪዎችን የአካባቢ ቅሬታዎች ያሰስታሉ፣ የቁጠጣ እርምጃዎችን ይመክራሉ እና በሕገወጥ ላይ በመከታተል ተገቢው የማስተካከያ ሥራ እንዲከናወን ያረጋግጣሉ። በተጨማሪም ለአካባቢ ፖሊሲ እድገት እና ለህዝባዊ ትምህርት ተቋሞች ያበርክታሉ ይህም በልደታ ማህበረሰብ ውስጥ ዘላቂ ልምዶችን ለማስተዋወቅ የተነደፈ ነው።","qualifications":["የአካባቢ ሳይንስ፣ የአካባቢ ምህንድስና፣ ኬሚስትሪ ወይም ተዛማጅ ዘርፍ የባችለር ዲግሪ በአካባቢ ደንቦች፣ በብክለት ቁጥጥር እና በአካባቢ ክትትል የተረጋገጠ የትምህርት ሥራ ጋር","ቢያንስ ሶስት ዓመት የሙያ ልምድ በአካባቢ ክትትል፣ በማጣጣል ክትትል፣ በብክለት ቁጥጥር ወይም በመንግሥት ወይም በኢንዱስትሪ ሁኔታዎች ውስጥ በአስተዳደር ማስከበር","በፌዴራል፣ ክልላዊ እና ከተማ ደረጃዎች ላይ የኢትዮጵያ የአካባቢ ሕጎች፣ ደንቦች፣ ደረጃዎች እና የፈቃድ መስፈርቶች ጥልቅ እውቀት፤ ከማስከበር ሂደቶች ጋር መረዳት","በአካባቢ ክትትል ቴክኒኮች፣ በናሙና ማውጣት ፕሮቶኮሎች፣ በመስክ የመለኪያ መሣሪያ እና በላቦራቶሪ ትንተና ዘዴዎች ላይ ቴክኒካዊ ችሎታ፤ ለአየር፣ ለውሃ እና ለአፈር ጥራት መለኪያዎች","በቴክኒካዊ ውሂብ ትርጉም መስጠት፣ በአስተዳደር ሕገወጥነቶችን መለየት እና በአደጋ ግምገማ ላይ በመመስረት ተገቢ የማስከበር ምላሾችን የመገንባት ችሎታ ጋር ጠንካራ የምርመራ እና የትንተና ክህሎቶች","ግልጽ፣ አጠቃላይ እና በሕግ ሊጠበቅ የሚችል የክትትል ሪፖርቶችን፣ የሕገወጥ ማስታወቂያዎችን እና የማጣጣል ሰነዶችን የመጻፍ ችሎታ ጋር አስተማማኝ የሪፖርት ጻፊያ እና የሰነድ ክህሎቶች","በተለያዩ ተጋሪዎች ላይ ውስብስብ የአካባቢ ደንቦችን ለማብራራት፣ የማጣጣል ስምምነቶችን ለማሸነፍ እና በግጭት ሁኔታዎች ውስጥ በሙያዊ ሁኔታ ለማስተዳደር ችሎታ ጋር ውጤታማ የመገናኛ እና በውስጥ ባለ ሰዎች ክህሎቶች","በተለያዩ አካባቢዎች ውስጥ በመስክ ክትትሎችን ለማካሄድ አካላዊ ችሎታ፤ ከኢንዱስትሪ ተቋማት፣ ከግንባታ ቦታዎች እና ከሊቅ የአደጋ ሁኔታዎች ጋር ተገቢ የደህንነት እርጥበት ጋር"],"responsibilities":["የኢንዱስትሪ ተቋማትን፣ የንግድ መስሪያ ቤቶችን፣ የግንባታ ቦታዎችን እና የአገልግሎት አቅራቢዎችን በተፈረመ እና በድንገተኛ ክትትሎች ያካሂዱ፤ ከአካባቢ ደንቦች፣ ፈቃዶች እና ደረጃዎች ጋር ማጣጣልን ይገምግሙ","ከነዋሪዎች የሚመጡ የአካባቢ ቅሬታዎችን በብክለት፣ በማያስቻል የነፍሳት ማስወገጃ፣ በድምፅ ሕገወጥነት እና በሌሎች የአካባቢ ግዴታዎች ላይ ያሰስቱ፤ ውጤቶችን በማስቀመጥ እና ተገቢ የማስከበር እርምጃዎችን በማመከር","ከአካባቢ ናሙናዎችን (አየር፣ ውሃ፣ አፈር) በመደበኛ ፕሮቶኮሎች በመከተል ይሰብስቡ፤ የላቦራቶሪ ትንተናን ያስተባብሩ፣ ውጤቶችን ይተረጉሙ እና በአካባቢ ጥራት እና በብክለት ደረጃዎች ላይ ቴክኒካዊ ሪፖርቶችን ያዘጋጁ","ለአካባቢ ደረጃዎች ለማይደርሱ ተቋማት የሕገወጥ ማስታወቂያዎችን፣ የማጣጣል ትዕዛዞችን እና የአስተዳደር ወንጀሎችን ያስተላልፉ፤ የማስከበር እርምጃዎች እና የተከታተል እንቅስቃሴዎችን ዝርዝር መዝገቦችን ያቆዩ","ለታቀዱ ልማቶች የአካባቢ ተጽዕኖ ግምገማዎችን እና የአስተዳደር ዕቅዶችን ይገምግሙ፤ ቴክኒካዊ ምክሮችን ይስጡ እና የቁጠጣ እርምጃዎችን አተገባበርን ይከታተሉ","የተቋማትን አጠቃላይ የአካባቢ አፈፃፀም ለመገምገም የአካባቢ ኦዲቶችን ያካሂዱ፤ ለማሻሻል እድሎችን ይለዩ እና ለቁጠጣ እርምጃዎች የማጣጣል ሰሌዳዎችን ይዘጋጁ","በማግኘት፣ በመታየት፣ በፎቶግራፍ፣ በመለኪያ እና በማጣጣል እና በአካባቢ ጥበቃ ምክሮች ላይ ያሉ ግምገማ ሪፖርቶችን ያዘጋጁ","በንግድ ባለቤቶች፣ በተቋም አስተዳዳሪዎች እና በማህበረሰብ አባላት ላይ የአካባቢ ደንቦች፣ የብክለት መከላከያ ቴክኒኮች እና ዘላቂ ልምዶችን በተመለከተ ቴክኒካዊ መመሪያ እና ትምህርት ይስጡ"],"short_description":"የአካባቢ ደንቦችን አስከብሩ እና የተቋም ክትትሎችን ያካሂዱ። ከአየር ጥራት እና ከነፍሳት አስተዳደር ደረጃዎች ጋር ማጣጣልን ያረጋግጡ።"}', '{"type":"Yeroo Guutuu","title":"Ilaala Naannoo","salary":"52000","category":"Naannoo","location":"Lideta Sub-City","description":"Mana hojii mootummaa Lideta Sub-City keessatti akka Ilaala Naannoo taateen, safuu naannoo dhaabuuf, ilaala dhaabbataa guutuu shirkii fi indaastirii gaggeessuufi, waliigala naannoo fi naannoo magaalaa wajhin walqabataa mirkaneessuuf dhaabbata. Rooliin kee qorannoo sirnaa bu\'aa baasa, tajaajila bulchiinsa saaphanaa, fi bu\'aa naannoo gochaalee adda addaa sub-city keessatti qorannoo dha. Ilaala xiqqaa ta\'e indaastirii oomishaa, bakka tajaajilaa, bakka ijaarsaa, fi hundeeffama jireenyaa walqabataa qulqullina qilleensa, tajaajilaa bishaan qubeessuu, safuu saaphanaa, fi daangeffama qubeessuu dhagaa ilaaluu dha. Kun beekumsa teknikaalaa saayinsii naannoo, qaama safuu, fi mala ilaalaa barbaachisa. Iciti jireenyaa naannoo ilaaluu, tarkaanfii sirrii yaaduufi, fi dhiibbaa sirrii mirkaneessuuf ba\'aa hawaasaa naannoo ilaaluu dha. Dabalataan, qopheessaa naannoo naannoo fi kaayyoo barsiisa ummataa hawaasa Lideta keessatti tajaajila dhaabbataa daddabsiisuuf kan qophaa\'e taatee dha.","qualifications":["Digirii Baachilerii Saayinsii Naannoo, Injinarii Naannoo, Kemistirii, ykn qoqqooda walitti dhufeenya irraa qophaa\'e mala safuu naannoo, tajaajilaa qubeessuu, fi ilaalaa naannoo","Waggaa sadi yoo ta\'u ol tajaajila hojii ilaalaa naannoo, eeguu walqabataa, tajaajilaa qubeessuu, ykn dhaabu safuu mootummaa ykn indaastirii keessatti","Beekumsa gadi fagoo seera naannoo Itoophiyaa, safuu, waliigala, fi hayyama murteessaa adda addaa fi federaalaa, naannoo, fi naannoo magaalaa, fi hubannaa tarsiimoo dhaabuuf","Dandeettii teknikaalaa mala ilaalaa naannoo, waliigalaa faayila qabsiifachuu, meeshaa safara naannoo, fi mala qorannoo laaboratoorii qulqullina qilleensa, bishaan, fi dhoqqee","Dandeettii qorannoofi qorannoo cimaa, fi dandeettii daataa teknikaalaa hiikuu, dhiibbaa safuu ilaaluu, fi deebii dhaabuuf sirrii ta\'e bu\'aa madaala dhibee irratti hundaa\'e qopheessuuf","Dandeettii barreeffama gabaa ol\'aanaa fi galmeeessuu, fi dandeettii ifaa, guutuu, fi seeraan eegamaa ta\'e gabaa ilaalaa, beeksisa dhiibbaa, fi galmee walqabataa qopheessuuf","Dandeettii bilbilaa fi dandeettii nama gidduu bu\'aa qabu, fi dandeettii safuu naannoo sirrii ta\'e haala adda addaa irratti ibsuu, walii galtee walqabataa mariisuu, fi haala dorgomaa akka hojii tiin bulchuuf","Dandeettii qaamaa ilaalaa naannoo haala adda addaa keessatti raawwachiisuuf, kanneen dhaabbataa indaastirii, bakka ijaarsaa, fi hawwa dhibee danda\'aa ta\'e, fi daandiiwwan nageenya sirrii wajhin"],"responsibilities":["Ilaala yeroo ykn ba\'a ta\'e indaastirii, bakka daldalaa, bakka ijaarsaa, fi kennawwan tajaajilaa safuu naannoo, hayyama, fi waliigalaa wajhin walqabataa ilaaluuf","Iciti jireenyaa naannoo jiraattoota irraa qorannoo, dhiibbaa saaphanaa sirrii ta\'e hin qabne, dhiibbaa dhagaa, fi dhimma naannoo biroo ilaaluu, argina galmeessuu, fi tarkaanfii dhaabuuf sirrii yaaduu","Faayila naannoo (qilleensa, bishaan, dhoqqee) waliigalaa hordofuun qabsiifadhu, qorannoo laaboratoorii walitti fiduu, bu\'aa hiikuu, fi gabaa teknikaalaa qulqullina naannoo fi sadarkaa qubeessuu irratti qopheessu","Beeksa dhiibbaa, ajaja walqabataa, fi kaffaltii bulchinsaa dhaabbatoonni waliigala naannoo hin milkaa\'in irratti kennuu, galmee sirrii ta\'e tarkaanfii dhaabuufi hordoffii hawaasaa turu","Qorannoo bu\'aa naannoo fi qophii bulchinsaa hundeeffama itti aanu ilaaluu, yaada teknikaalaa dhiyeessuu, fi raawwachiinsa tarkaanfii hir\'isuu ilaaluu","Auditii naannoo dhaabbataa irratti raawwachiisuun dandeettii naannoo guutuu ilaaluu, carraa fooyya\'insa ilaaluu, fi sa\'ataa sirrii tarkaanfii sirrii ta\'e qopheessuu","Gabaa ilaalaa guutuu kanneen argina, ilaalcha, suuraa, safara, fi yaada walqabataa safuu naannoo fi eeguu naannoo irratti qopheessu","Gorsa teknikaalaafi barsiisa abbaa daldalaa, bulchaa dhaabbataa, fi miseensa hawaasaa safuu naannoo, mala qubeessuu dhorguu, fi tajaajila dhaabbataa irratti kennu"],"short_description":"Safuu naannoo dhaabu, ilaala dhaabbataa gaggeessi. Walqabataa qulqullina qilleensaafi bulchiinsa saaphanaa ilaali."}', '2025-12-20 12:38:42'),
